/**
 * SymbolContext — Global Pair Filter
 *
 * Provides: { symbol, setSymbol, recentSymbols, categoryFilter }
 * Default: XAU/USD (chart + watchlist canonical for gold)
 * All tabs import useSymbol() and filter content
 */

import { createContext, useContext, useState, useCallback, type ReactNode } from 'react';

const ACTIVE_SYMBOL_KEY = 'tradingos.activeSymbol';
const RECENT_SYMBOLS_KEY = 'tradingos.recentSymbols';

function loadStoredSymbol(): string {
  try {
    const s = localStorage.getItem(ACTIVE_SYMBOL_KEY);
    if (s && s.trim()) return s.trim();
  } catch { /* noop */ }
  return 'XAU/USD';
}

function loadStoredRecents(fallback: string[]): string[] {
  try {
    const raw = localStorage.getItem(RECENT_SYMBOLS_KEY);
    if (raw) {
      const arr = JSON.parse(raw) as unknown;
      if (Array.isArray(arr) && arr.length) return arr.map(String).filter(Boolean).slice(0, 10);
    }
  } catch { /* noop */ }
  return fallback;
}

export interface SymbolContextValue {
  symbol: string;
  setSymbol: (s: string) => void;
  recentSymbols: string[];
  /** Apply symbol + recents from server without re-deriving recents (cloud sync). */
  hydrateFromWorkspaceServer: (sym: string, recents: string[]) => void;
  categoryFilter: string | null;
  setCategoryFilter: (c: string | null) => void;
}

const SymbolContext = createContext<SymbolContextValue>({
  symbol: 'XAU/USD',
  setSymbol: () => {},
  recentSymbols: ['XAU/USD', 'EUR/USD', 'GBP/USD', 'BTC/USD', 'US30'],
  hydrateFromWorkspaceServer: () => {},
  categoryFilter: null,
  setCategoryFilter: () => {},
});

export function SymbolProvider({ children }: { children: ReactNode }) {
  const defaultRecents = ['XAU/USD', 'EUR/USD', 'GBP/USD', 'BTC/USD', 'US30'];
  const [symbol, setSymbolRaw] = useState(loadStoredSymbol);
  const [recentSymbols, setRecentSymbols] = useState<string[]>(() =>
    loadStoredRecents(defaultRecents),
  );
  const [categoryFilter, setCategoryFilter] = useState<string | null>(null);

  const setSymbol = useCallback((s: string) => {
    setSymbolRaw(s);
    try {
      localStorage.setItem(ACTIVE_SYMBOL_KEY, s);
    } catch { /* noop */ }
    setRecentSymbols(prev => {
      const filtered = prev.filter(x => x !== s);
      const next = [s, ...filtered].slice(0, 10);
      try {
        localStorage.setItem(RECENT_SYMBOLS_KEY, JSON.stringify(next));
      } catch { /* noop */ }
      return next;
    });
  }, []);

  const hydrateFromWorkspaceServer = useCallback((sym: string, recents: string[]) => {
    const s = String(sym || '').trim() || 'XAU/USD';
    const r = Array.isArray(recents) && recents.length
      ? recents.map(String).filter(Boolean).slice(0, 10)
      : loadStoredRecents(defaultRecents);
    setSymbolRaw(s);
    setRecentSymbols(r);
    try {
      localStorage.setItem(ACTIVE_SYMBOL_KEY, s);
      localStorage.setItem(RECENT_SYMBOLS_KEY, JSON.stringify(r));
    } catch { /* noop */ }
  }, []);

  return (
    <SymbolContext.Provider
      value={{
        symbol,
        setSymbol,
        recentSymbols,
        hydrateFromWorkspaceServer,
        categoryFilter,
        setCategoryFilter,
      }}
    >
      {children}
    </SymbolContext.Provider>
  );
}

export function useSymbol() {
  return useContext(SymbolContext);
}

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from 'react';
import {
  cloneDefaultGroups,
  flattenWatchlistGroups,
  loadWatchlistGroupsFromStorage,
  normalizeWatchlistGroups,
  saveWatchlistGroupsToStorage,
  type WatchlistGroups,
  WATCHLIST_CATEGORY_ORDER,
} from '@/lib/watchlistDefaults';

export type WatchlistContextValue = {
  groups: WatchlistGroups;
  /** Unique symbols in category order (for ticker tape / top bar). */
  flatSymbols: string[];
  setGroups: (next: WatchlistGroups) => void;
  resetToDefaults: () => void;
  addSymbolToCategory: (category: string, symbol: string) => boolean;
  removeSymbol: (symbol: string) => void;
  moveSymbolToCategory: (symbol: string, targetCategory: string) => void;
};

const WatchlistContext = createContext<WatchlistContextValue | null>(null);

function normalizeSymbol(raw: string) {
  return String(raw || '').trim();
}

export function WatchlistProvider({ children }: { children: ReactNode }) {
  const [groups, setGroupsState] = useState<WatchlistGroups>(() => {
    const stored = loadWatchlistGroupsFromStorage();
    if (stored) return normalizeWatchlistGroups(stored);
    return cloneDefaultGroups();
  });

  useEffect(() => {
    saveWatchlistGroupsToStorage(groups);
  }, [groups]);

  const flatSymbols = useMemo(() => flattenWatchlistGroups(groups), [groups]);

  const setGroups = useCallback((next: WatchlistGroups) => {
    setGroupsState(normalizeWatchlistGroups(next));
  }, []);

  const resetToDefaults = useCallback(() => {
    setGroupsState(cloneDefaultGroups());
  }, []);

  const addSymbolToCategory = useCallback((category: string, raw: string) => {
    const sym = normalizeSymbol(raw);
    if (!sym) return false;
    const cat = WATCHLIST_CATEGORY_ORDER.includes(category as (typeof WATCHLIST_CATEGORY_ORDER)[number])
      ? category
      : 'FX';
    const result = { changed: false };
    setGroupsState((prev) => {
      const next = normalizeWatchlistGroups(prev);
      const currentCat = WATCHLIST_CATEGORY_ORDER.find((c) => (next[c] || []).includes(sym));
      if (currentCat === cat) {
        return prev;
      }
      for (const c of WATCHLIST_CATEGORY_ORDER) {
        next[c] = [...(next[c] || [])].filter((x) => x !== sym);
      }
      next[cat] = [...(next[cat] || []), sym];
      result.changed = true;
      return next;
    });
    return result.changed;
  }, []);

  const removeSymbol = useCallback((raw: string) => {
    const sym = normalizeSymbol(raw);
    if (!sym) return;
    setGroupsState((prev) => {
      const next = normalizeWatchlistGroups(prev);
      for (const c of WATCHLIST_CATEGORY_ORDER) {
        next[c] = [...(next[c] || [])].filter((x) => x !== sym);
      }
      return next;
    });
  }, []);

  const moveSymbolToCategory = useCallback((raw: string, targetCategory: string) => {
    const sym = normalizeSymbol(raw);
    if (!sym) return;
    const cat = WATCHLIST_CATEGORY_ORDER.includes(targetCategory as (typeof WATCHLIST_CATEGORY_ORDER)[number])
      ? targetCategory
      : 'FX';
    setGroupsState((prev) => {
      const next = normalizeWatchlistGroups(prev);
      for (const c of WATCHLIST_CATEGORY_ORDER) {
        next[c] = [...(next[c] || [])].filter((x) => x !== sym);
      }
      const list = [...(next[cat] || [])];
      if (!list.includes(sym)) list.push(sym);
      next[cat] = list;
      return next;
    });
  }, []);

  const value = useMemo<WatchlistContextValue>(
    () => ({
      groups,
      flatSymbols,
      setGroups,
      resetToDefaults,
      addSymbolToCategory,
      removeSymbol,
      moveSymbolToCategory,
    }),
    [groups, flatSymbols, setGroups, resetToDefaults, addSymbolToCategory, removeSymbol, moveSymbolToCategory],
  );

  return <WatchlistContext.Provider value={value}>{children}</WatchlistContext.Provider>;
}

export function useTerminalWatchlist() {
  const ctx = useContext(WatchlistContext);
  if (!ctx) {
    throw new Error('useTerminalWatchlist must be used within WatchlistProvider');
  }
  return ctx;
}

export function useTerminalWatchlistOptional(): WatchlistContextValue | null {
  return useContext(WatchlistContext);
}

