          </span>
        )}
      </div>
      <div className={s.header__stats}>
        <Stat label="PROJECTS"   value={fmtInt(totalProjects)} />
        <Stat label="GW CAPACITY" value={fmtMw(totalMw)} accent />
        <Stat label="INVESTMENT" value={fmtUsd(totalInvestment)} accent />
