export function Tooltip({ node, mode, timeframe, x, y, containerW }) {
  if (!node) return null;
  const t = node.raw;
  const pct = (t.changes && t.changes[timeframe]) ?? 0;
  const relVol = t.volume && t.avgVolume ? t.volume / t.avgVolume : 0;

  // clamp x so it doesn't spill out
  const width = 240;
  let left = x + 16;
  if (left + width > containerW) left = Math.max(0, x - width - 16);
  const top = y + 16;

  return (
    <div className={styles.tooltip} style={{ left, top, width }}>
      <div className={styles.tooltipHeader}>
        <span className={styles.tooltipSymbol}>{t.symbol}</span>
        <span
          className={styles.tooltipPct}
          data-direction={pct > 0 ? "up" : pct < 0 ? "down" : "flat"}
        >
          {pct > 0 ? "+" : ""}
          {pct.toFixed(2)}%
        </span>
      </div>
      <div className={styles.tooltipName}>{t.name}</div>
      <div className={styles.tooltipSpark}>
        <Sparkline values={t.sparkline || []} width={width - 24} height={34} />
      </div>
      <div className={styles.tooltipGrid}>
        <div>
          <span>PRICE</span>
          <strong>${formatPrice(t.price)}</strong>
        </div>
        <div>
          <span>MKT CAP</span>
          <strong>{formatMarketCap(t.marketCap)}</strong>
        </div>
        <div>
          <span>SECTOR</span>
          <strong>{t.sector}</strong>
        </div>
        <div>
          <span>P/E</span>
          <strong>{t.peRatio ? t.peRatio.toFixed(1) : "—"}</strong>
        </div>
        <div>
          <span>REL VOL</span>
          <strong>{relVol ? relVol.toFixed(2) + "x" : "—"}</strong>
        </div>
        <div>
          <span>{timeframe}</span>
          <strong>{formatMetric("performance", pct)}</strong>
        </div>
      </div>
    </div>
  );
}

export default Tooltip;

import React, { useMemo, useState } from "react";
import styles from "../styles/heatmap.module.css";
import { buildTreemap } from "../utils/treemap";
import { getMetricExtractor, getColorFn, formatMetric } from "../utils/color";
import { Tooltip } from "./Tooltip";

export function TreemapCanvas({ tickers, size, timeframe, metric }) {
  const [hover, setHover] = useState(null); // { node, x, y }

  const extractor = useMemo(
    () => getMetricExtractor(metric, timeframe),
    [metric, timeframe]
  );
  const colorFn = useMemo(() => getColorFn(metric), [metric]);

  const { sectors, nodes } = useMemo(() => {
    if (!size.w || !size.h) return { sectors: [], nodes: [] };
    return buildTreemap(
      tickers,
      { x: 0, y: 0, w: size.w, h: size.h },
      extractor,
      2,
      18
    );
  }, [tickers, size.w, size.h, extractor]);

  const handleMove = (node) => (e) => {
    const rect = e.currentTarget.parentElement.getBoundingClientRect();
    setHover({
      node,
      x: e.clientX - rect.left,
      y: e.clientY - rect.top,
    });
  };

  const handleLeave = () => setHover(null);

  return (
    <div className={styles.canvas}>
      {sectors.map((s) => (
        <React.Fragment key={s.sector}>
          <div
            className={styles.sectorHeader}
            style={{
              left: s.x,
              top: s.y,
              width: s.w,
              height: 18,
            }}
          >
            <span className={styles.sectorName}>{s.sector.toUpperCase()}</span>
            <span className={styles.sectorCount}>{s.tickers.length}</span>
          </div>
        </React.Fragment>
      ))}

      {nodes.map((n) => {
        const area = n.w * n.h;
        const showSymbol = area > 900;
        const showMetric = area > 2400;
        const showSmallOnly = area > 300 && area <= 900;
        const fill = colorFn(n.metricValue);
        return (
          <div
            key={n.symbol}
            className={styles.cell}
            style={{
              left: n.x,
              top: n.y,
              width: n.w,
              height: n.h,
              backgroundColor: fill,
            }}
            onMouseMove={handleMove(n)}
            onMouseLeave={handleLeave}
          >
            {showSymbol ? (
              <>
                <span className={styles.cellSymbol}>{n.symbol}</span>
                {showMetric ? (
                  <span className={styles.cellMetric}>
                    {formatMetric(metric, n.metricValue)}
                  </span>
                ) : null}
              </>
            ) : showSmallOnly ? (
              <span className={styles.cellSymbolSmall}>{n.symbol}</span>
            ) : null}
          </div>
        );
      })}

      {hover ? (
        <Tooltip
          node={hover.node}
          mode={metric}
          timeframe={timeframe}
          x={hover.x}
          y={hover.y}
          containerW={size.w}
        />
      ) : null}
    </div>
  );
}

export default TreemapCanvas;

/**
 * HeatmapV2 — Finviz-style market cap weighted treemap.
 * Adapter contract. Mirror this in your real adapter (FMP ultimate has
 * everything needed: marketCap, sector, price, changesPercentage, volume,
 * peRatio).
 */

export type Timeframe = "1D" | "1W" | "1M" | "YTD" | "1Y";

export type MetricMode = "performance" | "volume" | "pe";

export interface HeatmapTicker {
  symbol: string;
  name: string;
  sector: string;
  marketCap: number; // in USD, used for treemap area weighting
  price: number;
  // percentage change per timeframe (e.g. { "1D": 1.24, "1W": -2.1, ... })
  changes: Partial<Record<Timeframe, number>>;
  // optional extras for tooltip + metric modes
  volume?: number;
  avgVolume?: number;
  peRatio?: number;
  sparkline?: number[]; // small array of price points for hover preview
}

export interface HeatmapSnapshot {
  asOf: number; // epoch ms
  tickers: HeatmapTicker[];
}

export interface HeatmapDataSource {
  /**
   * Return a snapshot of all tickers. Implementations are free to cache
   * and throttle — the component will call this on mount and on manual
   * refresh. AbortSignal may be provided.
   */
  getSnapshot(signal?: AbortSignal): Promise<HeatmapSnapshot>;
}

export interface TreemapNode {
  symbol: string;
  name: string;
  sector: string;
  value: number; // weighting (market cap)
  metricValue: number; // driver for color (pct change, relVol, pe)
  raw: HeatmapTicker;
  x: number;
  y: number;
  w: number;
  h: number;
}

export interface TreemapSector {
  sector: string;
  value: number;
  x: number;
  y: number;
  w: number;
  h: number;
  tickers: TreemapNode[];
}

// ================================================================
// ContextPanels — wrapper that renders the 4 symbol-aware panels
// in left / right / both layouts. All panels share one dataSource
// and respond to the same `symbol` prop.
// ================================================================

import React from 'react';
import { AnalystConsensus } from './components/AnalystConsensus.jsx';
import { PeersRelative }    from './components/PeersRelative.jsx';
import { KeyLevels }        from './components/KeyLevels.jsx';
import { SentimentShort }   from './components/SentimentShort.jsx';
import { cx }               from './utils/format.js';
import s                    from './styles/context.module.css';

/**
 * @param {Object}  props
 * @param {Object}  props.dataSource        - ContextDataSource adapter
 * @param {string}  props.symbol            - Currently selected ticker
 * @param {'left'|'right'|'both'} [props.side='left']
 * @param {number}  [props.refreshInterval] - Override auto-refresh interval (ms)
 * @param {string}  [props.className]
 * @param {boolean} [props.naturalHeight] - Shrink to content; use when the outer column scrolls (News page).
 */
export function ContextPanels({
  dataSource,
  symbol,
  side = 'left',
  refreshInterval,
  className = '',
  naturalHeight = false,
}) {
  const commonProps = { dataSource, symbol };
  if (refreshInterval != null) commonProps.refreshInterval = refreshInterval;

  const wrap = (inner) => (
    <div className={cx(s.panels, naturalHeight && s.panelsNatural, className)}>{inner}</div>
  );

  if (side === 'left') {
    return wrap(
      <>
        <AnalystConsensus {...commonProps} />
        <PeersRelative    {...commonProps} />
      </>
    );
  }

  if (side === 'right') {
    return wrap(
      <>
        <KeyLevels       {...commonProps} />
        <SentimentShort  {...commonProps} />
      </>
    );
  }

  // side === 'both'
  return (
    <div className={cx(s.panels, s['panels--both'], className)}>
      <div className={cx(s.panels, naturalHeight && s.panelsNatural)}>
        <AnalystConsensus {...commonProps} />
        <PeersRelative    {...commonProps} />
      </div>
      <div className={cx(s.panels, naturalHeight && s.panelsNatural)}>
        <KeyLevels       {...commonProps} />
        <SentimentShort  {...commonProps} />
      </div>
    </div>
  );
}

// ================================================================
// AnalystConsensus — panel showing ratings breakdown, price target,
