        />
      )}
      {panels.includes('hotkeys') && <HotkeySheet rows={hotkeyRows} />}
    </div>
  );
}

// ================================================================
// HotkeySheet — compact cheat-sheet for the news terminal.
// Accepts a custom rows prop so your engine can override defaults.
// ================================================================

import React from 'react';
import { cx } from '../utils/format.js';
import s from '../styles/extras.module.css';

const DEFAULT_ROWS = [
  { group: 'NAVIGATION', keys: ['j'],           label: 'Next headline' },
  { group: 'NAVIGATION', keys: ['k'],           label: 'Previous headline' },
  { group: 'NAVIGATION', keys: ['g', 'g'],      label: 'Jump to top' },
  { group: 'NAVIGATION', keys: ['shift', 'g'],  label: 'Jump to end' },

  { group: 'FEEDS', keys: ['1'], label: 'Stock feed' },
  { group: 'FEEDS', keys: ['2'], label: 'Macro feed' },
  { group: 'FEEDS', keys: ['3'], label: 'Press releases' },
  { group: 'FEEDS', keys: ['4'], label: 'FMP feed' },

  { group: 'ACTIONS', keys: ['c'],        label: 'Mount chart for symbol' },
  { group: 'ACTIONS', keys: ['a'],        label: 'Add to watchlist' },
  { group: 'ACTIONS', keys: ['s'],        label: 'Save headline' },
  { group: 'ACTIONS', keys: ['/'],        label: 'Search / filter' },
  { group: 'ACTIONS', keys: ['enter'],    label: 'Open source' },
  { group: 'ACTIONS', keys: ['esc'],      label: 'Clear selection' },

  { group: 'SYMBOL', keys: ['shift', ':'], label: 'Command palette' },
  { group: 'SYMBOL', keys: ['.'],          label: 'Swap symbol' },
  { group: 'SYMBOL', keys: ['r'],          label: 'Force refresh' },
];

export function HotkeySheet({ rows, className = '', variant = 'panel' }) {
  const data = rows && rows.length ? rows : DEFAULT_ROWS;

  // Group rows preserving first-seen order
  const groups = [];
  const seen = new Map();
  for (const r of data) {
    const g = r.group || 'GENERAL';
    if (!seen.has(g)) {
      seen.set(g, groups.length);
      groups.push({ name: g, rows: [] });
    }
    groups[seen.get(g)].rows.push(r);
  }

  if (variant === 'banner') {
    return (
      <div className={cx(s.hotkeyBanner, className)} role="region" aria-label="Keyboard shortcuts">
        <span className={s.hotkeyBannerTag}>HOTKEYS</span>
        <div className={s.hotkeyBannerScroll}>
          {groups.map((g) => (
            <div key={g.name} className={s.hotkeyBannerGroup}>
              <span className={s.hotkeyBannerGroupLabel}>{g.name}</span>
              {g.rows.map((r, i) => (
                <span key={i} className={s.hotkeyBannerChip}>
                  <span className={s.hotkeyBannerKeys}>
                    {r.keys.map((k, j) => (
                      <React.Fragment key={j}>
                        {j > 0 && <span className={s.hkPlus}>+</span>}
                        <kbd className={s.kbdSm}>{formatKey(k)}</kbd>
                      </React.Fragment>
                    ))}
                  </span>
                  <span className={s.hotkeyBannerChipLabel}>{r.label}</span>
                </span>
              ))}
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className={cx(s.panel, s.elevation2, className)}>
      <div className={s.panel__head}>
        <span className={s.mono}>HOTKEYS</span>
        <span className={cx(s.mono, s.muted)}>TERMINAL</span>
      </div>

      <div className={s.hkBody}>
        {groups.map((g) => (
          <div key={g.name} className={s.hkGroup}>
            <div className={s.hkGroupLabel}>{g.name}</div>
            <div className={s.hkRows}>
              {g.rows.map((r, i) => (
                <div key={i} className={s.hkRow}>
                  <span className={s.hkKeys}>
                    {r.keys.map((k, j) => (
                      <React.Fragment key={j}>
                        {j > 0 && <span className={s.hkPlus}>+</span>}
                        <kbd className={s.kbd}>{formatKey(k)}</kbd>
                      </React.Fragment>
                    ))}
                  </span>
                  <span className={s.hkLabel}>{r.label}</span>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function formatKey(k) {
  const map = { shift: '⇧', ctrl: '⌃', cmd: '⌘', alt: '⌥', enter: '↵', esc: 'esc' };
  return map[k] ?? k;
}

// ================================================================
// NextCatalysts — upcoming events grouped by time.
// Pulls from catalystsDataSource.fetchCatalysts, which your
// shared engine should stitch together from the earnings calendar,
// macro calendar, Fed schedule, and custom events.
// ================================================================

import React, { useMemo } from 'react';
import { useAsync } from '../hooks/useAsync.js';
import {
  cx,
  relativeTime,
  absoluteClock,
  CATALYST_COLOR,
} from '../utils/format.js';
import s from '../styles/extras.module.css';

export function NextCatalysts({
  dataSource,
  symbol,
  windowHours = 48,
  refreshInterval = 60_000,
  className = '',
  variant = 'default',
}) {
  const q = useAsync({
    fetcher: dataSource
      ? ({ signal }) => dataSource.fetchCatalysts({ windowHours, symbol: symbol ?? null, signal })
      : null,
    deps: [dataSource, windowHours, symbol],
    refreshInterval,
  });

  const items = q.data?.catalysts || [];
  const { imminent, today, upcoming } = useMemo(() => groupCatalysts(items), [items]);

  return (
    <div
      className={cx(
        s.panel,
        s.elevation2,
        variant === 'sidebar' && s.panelSidebar,
        className,
      )}
    >
      <div className={s.panel__head}>
        <span className="tos-block-title">NEXT CATALYSTS</span>
        <span className={cx(s.mono, s.muted)}>{windowHours}h · {items.length}</span>
      </div>

      {q.loading && !items.length ? (
        <Skel rows={4} />
      ) : q.error ? (
        <div className={s.error}>{(q.error.message || 'FAILED').toUpperCase()}</div>
      ) : items.length === 0 ? (
        <div className={s.empty}>NO CATALYSTS IN WINDOW</div>
      ) : (
        <>
          {imminent.length > 0 && (
            <Group label="< 2H" items={imminent} highlight />
          )}
          {today.length > 0 && (
            <Group label="TODAY" items={today} />
          )}
          {upcoming.length > 0 && (
            <Group label="UPCOMING" items={upcoming} />
          )}
        </>
      )}
    </div>
  );
}

function Group({ label, items, highlight }) {
  return (
    <div className={s.group}>
      <div className={cx(s.groupHead, highlight && s['groupHead--urgent'])}>
        <span>{label}</span>
        <span className={cx(s.mono, s.muted)}>{items.length}</span>
      </div>
      <div className={s.catList}>
        {items.map((c) => (
          <CatalystRow key={c.id} catalyst={c} highlight={highlight} />
        ))}
      </div>
    </div>
  );
}

function CatalystRow({ catalyst, highlight }) {
  const color = CATALYST_COLOR[catalyst.kind] || '#9aa0a6';
  return (
    <div
      className={cx(s.cat, highlight && s['cat--urgent'])}
      onClick={() =>
        catalyst.sourceUrl && window.open(catalyst.sourceUrl, '_blank', 'noopener')
      }
      style={{ cursor: catalyst.sourceUrl ? 'pointer' : 'default' }}
    >
      <span className={s.catDot} style={{ background: color }} />
      <div className={s.catText}>
        <div className={s.catTitle}>
          {catalyst.symbol && (
            <span className={s.catSym}>{catalyst.symbol}</span>
          )}
          <span>{catalyst.title}</span>
          {catalyst.note && (
            <span className={cx(s.mono, s.muted, s.catNote)}>{catalyst.note}</span>
          )}
        </div>
        <div className={s.catSub}>
          <span className={cx(s.mono, s.muted)}>{absoluteClock(catalyst.startAt)}</span>
          <span className={s.sep}>·</span>
          <span className={cx(s.mono, highlight ? s.up : s.muted)}>
            {relativeTime(catalyst.startAt)}
          </span>
        </div>
      </div>
      <span
        className={cx(s.impact, s['impact--' + (catalyst.impact || 'low')])}
        aria-label={`Impact ${catalyst.impact}`}
      />
    </div>
  );
}

function Skel({ rows }) {
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 4, padding: 4 }}>
      {Array.from({ length: rows }).map((_, i) => (
        <div key={i} className={s.skel} style={{ height: 36 }} />
      ))}
    </div>
  );
}

function groupCatalysts(items) {
  const now = Date.now();
  const twoH = 2 * 60 * 60 * 1000;
  const endOfTodayUtc = new Date();
  endOfTodayUtc.setUTCHours(23, 59, 59, 999);
  const endOfToday = endOfTodayUtc.getTime();

  const imminent = [];
  const today = [];
  const upcoming = [];

  const sorted = [...items].sort(
    (a, b) => new Date(a.startAt).getTime() - new Date(b.startAt).getTime(),
  );

  for (const c of sorted) {
    const t = new Date(c.startAt).getTime();
    const diff = t - now;
    if (diff <= 0) continue;                // skip past
    if (diff <= twoH)           imminent.push(c);
    else if (t <= endOfToday)   today.push(c);
    else                        upcoming.push(c);
  }
  return { imminent, today, upcoming };
}

// ================================================================
// QuickAlerts — 1-click alert templates + active alerts list.
// Pure presentation; state lives upstream in the parent engine.
// ================================================================

import React, { useMemo, useState } from 'react';
import { useAsync } from '../hooks/useAsync.js';
import {
  cx,
  relativeTime,
  ALERT_CATEGORY_COLOR,
  ALERT_CATEGORY_LABEL,
} from '../utils/format.js';
import s from '../styles/extras.module.css';

export function QuickAlerts({
  dataSource,
  symbol,
  refreshInterval = 45_000,
  className = '',
  variant = 'default',
}) {
  const [filter, setFilter] = useState('all'); // 'all' | AlertCategory

  const templatesQ = useAsync({
    fetcher: dataSource ? ({ signal }) => dataSource.listTemplates({ signal }) : null,
    deps: [dataSource],
  });
  const activeQ = useAsync({
    fetcher: dataSource
      ? ({ signal }) => dataSource.listActive({ symbol: symbol ?? null, signal })
      : null,
    deps: [dataSource, symbol],
    refreshInterval,
  });

  const templates = templatesQ.data || [];
  const active    = activeQ.data || [];

  const filtered = useMemo(
    () => (filter === 'all' ? templates : templates.filter((t) => t.category === filter)),
    [templates, filter],
  );

  const handleCreate = async (tpl) => {
    if (!dataSource?.createFromTemplate) return;
    try {
      await dataSource.createFromTemplate({ templateId: tpl.id, symbol: symbol ?? null });
      activeQ.refetch();
    } catch (_) { /* swallow; parent surfaces errors */ }
  };

  const handleToggle = async (alert) => {
    if (!dataSource?.toggle) return;
    try {
      await dataSource.toggle({ alertId: alert.id, enabled: !alert.enabled });
      activeQ.refetch();
    } catch (_) { /* noop */ }
  };

  const handleRemove = async (alert) => {
    if (!dataSource?.remove) return;
    try {
      await dataSource.remove({ alertId: alert.id });
      activeQ.refetch();
    } catch (_) { /* noop */ }
  };

  return (
    <div
      className={cx(
        s.panel,
        s.elevation2,
        variant === 'sidebar' && s.panelSidebar,
        className,
      )}
    >
      <div className={s.panel__head}>
        <span className="tos-block-title">1-CLICK ALERTS</span>
        <span className={cx(s.mono, s.muted)}>{symbol || 'GLOBAL'}</span>
      </div>

      <CategoryStrip
        active={filter}
        onChange={setFilter}
        counts={templateCounts(templates)}
      />

      <div className={s.templateList}>
        {templatesQ.loading && !templates.length ? (
          <Skel rows={5} height={38} />
        ) : templatesQ.error ? (
          <div className={s.error}>TEMPLATES FAILED</div>
        ) : filtered.length === 0 ? (
          <div className={s.empty}>NO TEMPLATES</div>
        ) : (
          filtered.map((tpl) => (
            <TemplateRow key={tpl.id} tpl={tpl} onCreate={handleCreate} />
          ))
        )}
      </div>

      <div className={s.sectionHead}>
        <span>ACTIVE ALERTS</span>
        <span className={cx(s.mono, s.muted)}>{active.length}</span>
      </div>
      <div className={s.activeList}>
        {activeQ.loading && !active.length ? (
          <Skel rows={2} height={28} />
        ) : activeQ.error ? (
          <div className={s.error}>ACTIVE LIST FAILED</div>
        ) : active.length === 0 ? (
          <div className={s.empty}>NO ACTIVE ALERTS</div>
        ) : (
          active.map((a) => (
            <ActiveRow key={a.id} alert={a} onToggle={handleToggle} onRemove={handleRemove} />
          ))
        )}
      </div>
    </div>
  );
}

function templateCounts(templates) {
  const out = { all: templates.length };
  for (const t of templates) out[t.category] = (out[t.category] || 0) + 1;
  return out;
}

function CategoryStrip({ active, onChange, counts }) {
  const items = [
    { key: 'all',            label: 'ALL' },
    { key: 'price',          label: 'PRICE' },
    { key: 'technical',      label: 'TECH' },
    { key: 'volume',         label: 'VOL' },
    { key: 'short_interest', label: 'SHORT' },
    { key: 'options',        label: 'OPT' },
    { key: 'news',           label: 'NEWS' },
    { key: 'macro',          label: 'MACRO' },
  ];
  return (
    <div className={s.chipRow}>
      {items.map((c) => (
        <button
          key={c.key}
          type="button"
          className={cx(s.chip, active === c.key && s['chip--active'])}
          onClick={() => onChange(c.key)}
        >
          <span
            className={s.chipDot}
            style={{
              background:
                c.key === 'all'
                  ? 'linear-gradient(135deg, #4ea1ff, #1fbf75, #f5a524)'
                  : ALERT_CATEGORY_COLOR[c.key] || '#9aa0a6',
            }}
          />
          {c.label}
          <span className={s.chipCount}>{counts?.[c.key] ?? 0}</span>
        </button>
      ))}
    </div>
  );
}

function TemplateRow({ tpl, onCreate }) {
  return (
    <div className={s.template} onClick={() => onCreate(tpl)} role="button" tabIndex={0}>
      <span
        className={s.templateDot}
        style={{ background: ALERT_CATEGORY_COLOR[tpl.category] || '#9aa0a6' }}
      />
      <div className={s.templateText}>
        <div className={s.templateTitleRow}>
          <span className={s.templateTitle}>{tpl.title}</span>
          {tpl.badge && <span className={s.badge}>{tpl.badge}</span>}
        </div>
        <div className={s.templateSub}>
          <span className={cx(s.mono, s.muted)}>
            {ALERT_CATEGORY_LABEL[tpl.category] || tpl.category.toUpperCase()}
          </span>
          {tpl.paramSummary && (
            <>
              <span className={s.sep}>·</span>
              <span className={cx(s.mono, s.muted)}>{tpl.paramSummary}</span>
            </>
          )}
        </div>
      </div>
      <span className={s.addBtn} aria-hidden>+</span>
    </div>
  );
}

function ActiveRow({ alert, onToggle, onRemove }) {
  return (
    <div className={cx(s.active, !alert.enabled && s['active--off'])}>
      <button
        type="button"
        className={cx(s.toggle, alert.enabled && s['toggle--on'])}
        onClick={() => onToggle(alert)}
        aria-label={alert.enabled ? 'Disable alert' : 'Enable alert'}
      >
        <span className={s.toggleKnob} />
      </button>
      <div className={s.activeText}>
        <div className={s.activeTitle}>{alert.title}</div>
        <div className={s.activeDetail}>
          <span className={cx(s.mono, s.muted)}>{alert.detail}</span>
          {alert.lastTriggeredAt && (
            <>
              <span className={s.sep}>·</span>
              <span className={cx(s.mono, s.muted)}>
                fired {relativeTime(alert.lastTriggeredAt)}
              </span>
            </>
          )}
        </div>
      </div>
      <button
        type="button"
        className={s.removeBtn}
        onClick={() => onRemove(alert)}
        aria-label="Remove alert"
      >
        ×
      </button>
    </div>
  );
}

function Skel({ rows = 4, height = 32 }) {
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
      {Array.from({ length: rows }).map((_, i) => (
        <div key={i} className={s.skel} style={{ height }} />
      ))}
    </div>
  );
}

// ================================================================
// useAsync — generic data-fetching hook with AbortSignal and
// optional refresh interval. Keeps stale data visible during
// background refreshes.
// ================================================================

import { useEffect, useRef, useState, useCallback } from 'react';

export function useAsync({ fetcher, deps = [], refreshInterval = 0 }) {
  const [data, setData]       = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError]     = useState(null);
  const tick = useRef(0);

  const run = useCallback(() => {
    if (!fetcher) return () => {};
    const controller = new AbortController();
    let cancelled = false;
    tick.current += 1;
    const id = tick.current;
    setLoading(true);
    Promise.resolve(fetcher({ signal: controller.signal }))
      .then((res) => {
        if (cancelled || id !== tick.current) return;
        setData(res);
        setError(null);
      })
      .catch((e) => {
        if (cancelled || e?.name === 'AbortError') return;
        setError(e instanceof Error ? e : new Error(String(e)));
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
      controller.abort();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps);

  useEffect(() => {
    const cleanup = run();
    let timer = null;
    if (refreshInterval > 0) {
      timer = setInterval(() => run(), refreshInterval);
    }
    return () => {
      if (cleanup) cleanup();
      if (timer) clearInterval(timer);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [run, refreshInterval]);

  return { data, loading, error, refetch: run };
}

