// ================================================================
// CommandBar — autocomplete search input
// Pulls dataSource from NewsContext; calls useSymbolSearch.
// ================================================================

import React, { useCallback, useContext, useEffect, useRef, useState } from 'react';
import { NewsContext } from '../context/NewsContext.jsx';
import styles from '../styles/news.module.css';
import { cx } from '../utils/format.js';
import { useSymbolSearch } from '../hooks/useSymbolSearch.js';

export function CommandBar({ onSelectSymbol, searchInputRef, onHideSuggestions }) {
  const { dataSource } = useContext(NewsContext);
  const [query, setQuery]         = useState('');
  const [activeIdx, setActiveIdx] = useState(-1);
  const [open, setOpen]           = useState(false);
  const inputRef                  = useRef(null);
  const wrapRef                   = useRef(null);

  // Expose focus-handle to parent
  useEffect(() => {
    if (!searchInputRef) return;
    searchInputRef.current = {
      focus: () => {
        inputRef.current?.focus();
        inputRef.current?.select();
      },
      setValue: (v) => setQuery(v),
      blur: () => inputRef.current?.blur(),
    };
  }, [searchInputRef]);

  const { results } = useSymbolSearch({ dataSource, query, enabled: true });

  // Close suggestions on outside click
  useEffect(() => {
    const onClick = (e) => {
      if (!wrapRef.current?.contains(e.target)) setOpen(false);
    };
    document.addEventListener('click', onClick);
    return () => document.removeEventListener('click', onClick);
  }, []);

  useEffect(() => {
    if (query && results.length) setOpen(true);
    if (!query) setOpen(false);
    setActiveIdx(-1);
  }, [query, results]);

  // Parent hook to imperatively close suggestions
  useEffect(() => {
    if (!onHideSuggestions) return;
    // no-op — parent reads ref it passed to useKeyboardNav; we listen via effect on `open`
  }, [onHideSuggestions]);

  const select = useCallback((sym) => {
    onSelectSymbol(sym);
    setQuery(sym);
    setOpen(false);
    inputRef.current?.blur();
  }, [onSelectSymbol]);

  const onKeyDown = (e) => {
    if (!open || !results.length) {
      if (e.key === 'Enter') {
        e.preventDefault();
        const q = query.trim().toUpperCase();
        if (q) select(q);
      }
      return;
    }
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setActiveIdx((i) => (i + 1) % results.length);
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setActiveIdx((i) => (i - 1 + results.length) % results.length);
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (activeIdx >= 0) select(results[activeIdx].symbol);
      else {
        const q = query.trim().toUpperCase();
        if (q) select(q);
      }
    } else if (e.key === 'Escape') {
      setOpen(false);
      inputRef.current?.blur();
    }
  };

  return (
    <form
      className={styles.cmdbar}
      role="search"
      onSubmit={(e) => e.preventDefault()}
      ref={wrapRef}
    >
      <span className={styles.cmdbarPrefix} title="Focus with /">/</span>
      <input
        ref={inputRef}
        type="text"
        placeholder="Symbol (AAPL) · company name · keyword — press / to focus"
        spellCheck={false}
        autoComplete="off"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        onFocus={() => query && results.length && setOpen(true)}
        onKeyDown={onKeyDown}
      />
      {open && results.length > 0 && (
        <div className={cx(styles.suggestions, styles.elevation3)}>
          {results.map((it, i) => (
            <div
              key={it.symbol}
              className={cx(styles.suggestion, i === activeIdx && styles.suggestionActive)}
              onMouseDown={(e) => { e.preventDefault(); select(it.symbol); }}
              onMouseEnter={() => setActiveIdx(i)}
            >
              <span className={styles.suggestionSym}>{it.symbol}</span>
              <span className={styles.suggestionName}>{it.name || ''}</span>
              <span className={styles.suggestionExch}>{it.exchange || ''}</span>
            </div>
          ))}
        </div>
      )}
      <div className={styles.cmdbarHints}>
        <kbd>/</kbd><kbd>j</kbd><kbd>k</kbd><kbd>1-4</kbd><kbd>r</kbd>
      </div>
    </form>
  );
}

// ================================================================
// FeedPanel — center feed with header, row list, footer
// Filter is applied against item.tags[] (array from your engine).
// ================================================================

import React, { useContext, useCallback, useRef, useEffect } from 'react';
import { NewsContext } from '../context/NewsContext.jsx';
import { FeedRow } from './FeedRow.jsx';
import { hhmm } from '../utils/format.js';
import s from '../styles/news.module.css';

function SkeletonRows() {
  return (
    <>
      {Array.from({ length: 8 }).map((_, i) => (
        <div key={i} className={`${s.skel} ${s['skel-row']}`} />
      ))}
    </>
  );
}

function feedTitle(feed, symbol) {
  switch (feed) {
    case 'stock':    return symbol ? `STOCK NEWS · ${symbol}` : 'STOCK NEWS · LATEST';
    case 'general':  return 'MACRO · LATEST';
    case 'press':    return symbol ? `PRESS · ${symbol}` : 'PRESS RELEASES · LATEST';
    case 'articles': return 'ARTICLES';
    default:         return '';
  }
}

function filterItems(items, filter) {
  if (filter === 'ALL') return items;
  return items.filter((it) => Array.isArray(it.tags) && it.tags.includes(filter));
}

export function FeedPanel({
  items,
  loading,
  error,
  pendingNew,
  lastUpdate,
  onLoadMore,
  onClearPendingNew,
  onSelectSymbol,
  selectedIndex,
  setSelectedIndex,
  onRefresh,
}) {
  const { feed, symbol, filter } = useContext(NewsContext);
  const listRef = useRef(null);

  useEffect(() => {
    if (selectedIndex < 0 || !listRef.current) return;
    const el = listRef.current.querySelector(`[data-index="${selectedIndex}"]`);
    if (el) el.scrollIntoView({ block: 'nearest' });
  }, [selectedIndex]);

  const handleSelect = useCallback((index) => setSelectedIndex(index), [setSelectedIndex]);
  const handleOpen   = useCallback((url) => { if (url) window.open(url, '_blank', 'noopener'); }, []);
  const handleBadge  = useCallback(() => {
    onClearPendingNew();
    listRef.current?.scrollTo({ top: 0, behavior: 'smooth' });
  }, [onClearPendingNew]);

  const filtered = filterItems(items, filter);
  const title = feedTitle(feed, symbol);

  return (
    <section className={`${s.feed} ${s['elevation-2']}`}>
      {/* Header */}
      <div className={s.feed__head}>
        <div className={s.feed__headL}>
          <h2 className={s.mono}>{title}</h2>
          {pendingNew > 0 && (
            <span
              className={s.newbadge}
              onClick={handleBadge}
              style={{ cursor: 'pointer' }}
            >
              {pendingNew} NEW
            </span>
          )}
        </div>
        <div className={s.feed__headR}>
          <span className={`${s.mono} ${s.muted}`}>
            {lastUpdate ? `Updated ${hhmm(lastUpdate)}` : '—'}
          </span>
          <button className={s.iconbtn} title="Refresh (r)" onClick={onRefresh} type="button">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
              <polyline points="23 4 23 10 17 10" />
              <polyline points="1 20 1 14 7 14" />
              <path d="M3.51 9a9 9 0 0 1 14.85-3.36L23 10" />
              <path d="M1 14l4.64 4.36A9 9 0 0 0 20.49 15" />
            </svg>
          </button>
        </div>
      </div>

      {/* Row list */}
      <div ref={listRef} className={s.rowlist} tabIndex={0} aria-live="polite">
        {loading && !items.length ? (
          <SkeletonRows />
        ) : error ? (
          <div className={s.error}>{(error.message || 'FEED ERROR').toUpperCase()}</div>
        ) : filtered.length === 0 ? (
          <div className={s.empty}>NO HEADLINES MATCH · TRY ANOTHER FILTER OR FEED</div>
        ) : (
          filtered.map((item, i) => (
            <FeedRow
              key={item.id}
              item={item}
              index={i}
              isSelected={i === selectedIndex}
              onSelect={handleSelect}
              onOpen={handleOpen}
              onSymbolClick={onSelectSymbol}
            />
          ))
        )}
      </div>

      {/* Footer */}
      <div className={s.feed__foot}>
        <button
          className={`${s.btn} ${s['btn--ghost']} ${s['btn--sm']}`}
          onClick={onLoadMore}
          disabled={loading}
          type="button"
        >
          {loading ? 'Loading…' : 'Load more'}
        </button>
        <span className={`${s.mono} ${s.muted}`}>
          {filtered.length}/{items.length} items · {filter}
        </span>
      </div>
    </section>
  );
}

// ================================================================
// FeedRow — single compact row in the primary feed (memoized)
// Consumes NewsItem shape: { id, title, text, publishedAt, url,
// publisher, symbols: string[], tags: string[] }
// ================================================================

import React, { memo } from 'react';
import { hhmm, ago } from '../utils/format.js';
import s from '../styles/news.module.css';

function primaryTag(tags) {
  if (!tags || !tags.length) return '';
  return tags[0];
}

function tagClass(tag) {
  return tag === 'M&A' ? 'MA' : tag;
}

/**
 * @param {{
 *   item: import('../types.d.ts').NewsItem,
 *   index: number,
 *   isSelected: boolean,
 *   onSelect: (index: number) => void,
 *   onOpen: (url: string) => void,
 *   onSymbolClick: (sym: string) => void,
 * }} props
 */
export const FeedRow = memo(function FeedRow({
  item,
  index,
  isSelected,
  onSelect,
  onOpen,
  onSymbolClick,
}) {
  const symbols = Array.isArray(item.symbols) ? item.symbols : [];
  const symLabel = symbols[0] || '—';
  const symEmpty = !symbols.length;

  const tag = primaryTag(item.tags);
  const tc = tagClass(tag);

  function handleClick() {
    onSelect(index);
    if (symbols[0]) onSymbolClick(symbols[0].toUpperCase());
  }

  function handleDblClick() {
    if (item.url) onOpen(item.url);
  }

  const rowCls = [
    s.row,
    item._isNew  ? s['is-new']      : '',
    isSelected   ? s['is-selected'] : '',
  ].filter(Boolean).join(' ');

  return (
    <div
      className={rowCls}
      onClick={handleClick}
      onDoubleClick={handleDblClick}
      data-url={item.url || ''}
      data-symbol={symbols[0] || ''}
      data-index={index}
    >
      <span className={s.row__time}>{hhmm(item.publishedAt)}</span>
      <span className={s.row__ago}>{ago(item.publishedAt)}</span>
      <span className={`${s.row__sym} ${symEmpty ? s['is-empty'] : ''}`}>{symLabel}</span>
      {tag && (
        <span className={`${s.row__tag} ${s['row__tag--' + tc] || ''}`}>{tag}</span>
      )}
      <span className={s.row__headline}>{item.title || '(no title)'}</span>
      <span className={s.row__site}>{(item.publisher || '').slice(0, 12)}</span>
    </div>
  );
});

