function Skeleton() {
  return (
    <div style={{ padding: '14px 16px' }}>
      <div className={s.skel} style={{ height: 20, width: '50%' }} />
      <div className={s.skel} style={{ height: 32, width: '70%', marginTop: 12 }} />
