      </span>
      <span className={`${s.mono} ${s.muted}`}>
        {reqCount} req · {errCount} err · {status}
      </span>
      <span className={`${s.mono} ${s.muted}`}>
        v2.0
      </span>
    </footer>
  );
}

// ================================================================
// TickerTape — horizontal watchlist tape with live-ish quotes
// Pulls data via dataSource.fetchTicker() through useTicker hook.
// ================================================================

import React, { useContext } from 'react';
import { NewsContext } from '../context/NewsContext.jsx';
import { useTicker } from '../hooks/useTicker.js';
import styles from '../styles/news.module.css';
import { cx, fmtPrice, fmtPct } from '../utils/format.js';

/**
 * @param {{ watchlist: string[], onSelectSymbol: (sym: string) => void }} props
 */
export function TickerTape({ watchlist, onSelectSymbol }) {
  const { dataSource } = useContext(NewsContext);
  const { quotes } = useTicker({ dataSource, symbols: watchlist });

  if (!watchlist.length) {
    return (
      <div className={cx(styles.tapebar, styles.elevation2)}>
        <div className={cx(styles.muted, styles.mono)} style={{ padding: '4px 8px', fontSize: 11 }}>
          WATCHLIST EMPTY
        </div>
      </div>
    );
  }

  return (
    <div className={cx(styles.tapebar, styles.elevation2)}>
      <div className={styles.tape}>
        {watchlist.slice(0, 16).map((sym) => {
          const q = quotes[sym];
          if (!q) {
            return (
              <button
                key={sym}
                className={styles.tapeItem}
                onClick={() => onSelectSymbol(sym)}
                type="button"
              >
                <span className={styles.tapeItemSym}>{sym}</span>
                <span className={styles.tapeItemPrice}>—</span>
              </button>
            );
          }
          const pct = q.changesPercentage ?? q.changePercentage ?? 0;
          const up = (q.change ?? 0) >= 0;
          return (
            <button
              key={sym}
              className={styles.tapeItem}
              onClick={() => onSelectSymbol(sym)}
              type="button"
            >
              <span className={styles.tapeItemSym}>{sym}</span>
              <span className={styles.tapeItemPrice}>${fmtPrice(q.price)}</span>
              <span className={cx(styles.tapeItemChg, up ? styles.up : styles.down)}>
                {up ? '▲' : '▼'} {fmtPct(pct)}
              </span>
            </button>
          );
        })}
      </div>
    </div>
  );
}

// ================================================================
// TopBar — brand + command bar + clock + status + help
// Pulls status from context; no API-key UI.
// ================================================================

import React, { useContext, useEffect, useState } from 'react';
import { NewsContext } from '../context/NewsContext.jsx';
import styles from '../styles/news.module.css';
import { cx } from '../utils/format.js';
import { CommandBar } from './CommandBar.jsx';

const STATUS_LABEL = {
  idle:    'IDLE',
  loading: 'SYNC',
  live:    'LIVE',
  error:   'ERR',
};

export function TopBar({ onSelectSymbol, onShowHelp, searchInputRef, onHideSuggestions }) {
  const { status } = useContext(NewsContext);
  const [clock, setClock] = useState('--:--:--');

  useEffect(() => {
    const tick = () => {
      const now = new Date();
      const loc = now.toLocaleTimeString('en-US', { hour12: false });
      const utc = now.toISOString().substring(11, 19);
      setClock(`${loc} · ${utc} UTC`);
    };
    tick();
    const t = setInterval(tick, 1000);
    return () => clearInterval(t);
  }, []);

  const statusCls =
    status === 'live'    ? styles.statusLive :
    status === 'error'   ? styles.statusError :
    status === 'loading' ? styles.statusLoading : '';

  return (
    <header className={cx(styles.topbar, styles.elevation1)}>
      <div className={styles.topbarBrand}>
        <span className={styles.logoDot} />
        <div>
          <div className={styles.brandSub}>NEWS · TERMINAL</div>
        </div>
      </div>

      <CommandBar
        onSelectSymbol={onSelectSymbol}
        searchInputRef={searchInputRef}
        onHideSuggestions={onHideSuggestions}
      />

      <div className={styles.topbarActions}>
        <div className={cx(styles.clock, styles.mono)} title="Local · UTC">{clock}</div>
        <div className={cx(styles.status, statusCls)} title="Data status">
          <span className={styles.statusIndicator} />
          <span className={styles.statusLabel}>{STATUS_LABEL[status] || 'IDLE'}</span>
        </div>
        <button
          className={styles.iconbtn}
          onClick={onShowHelp}
          title="Keyboard shortcuts (?)"
          type="button"
        >
          ?
        </button>
      </div>
    </header>
  );
}

// ================================================================
// NewsContext — shared state for the news module.
//
// Holds: dataSource (adapter), symbol, feed, filter, stream,
// request/error counters, and status. All FMP/Supabase concerns
// have been removed — your engine is the data source.
// ================================================================

import React, { createContext, useCallback, useRef, useState } from 'react';
import { STORAGE } from '../utils/constants';

/** @type {React.Context<import('../types.d.ts').NewsContextValue|null>} */
export const NewsContext = createContext(null);

function loadPref(key, fallback) {
  try {
    const v = localStorage.getItem(key);
    return v !== null ? v : fallback;
  } catch {
    return fallback;
  }
}

/**
 * NewsProvider — wraps NewsTab internals.
 * @param {{
 *   children: React.ReactNode,
 *   dataSource: import('../types.d.ts').DataSource,
 *   initialSymbol?: string|null,
 *   initialFeed?: import('../types.d.ts').FeedKey
 * }} props
 */
export function NewsProvider({ children, dataSource, initialSymbol = null, initialFeed }) {
  const [symbol, setSymbolState] = useState(initialSymbol);
  const [feed,   setFeedState]   = useState(() => initialFeed || loadPref(STORAGE.feed, 'stock'));
  const [filter, setFilterState] = useState(() => loadPref(STORAGE.filter, 'ALL'));
  const [stream, setStreamState] = useState(() => loadPref(STORAGE.stream, '1') === '1');
  const [status, setStatusState] = useState('idle');

  // Request/error counters — ref + state mirror avoids stale closures
  const reqRef = useRef(0);
  const errRef = useRef(0);
  const [reqCount, setReqCount] = useState(0);
  const [errCount, setErrCount] = useState(0);

  const setSymbol = useCallback((sym) => {
    setSymbolState(sym ? String(sym).toUpperCase() : null);
  }, []);

  const setFeed = useCallback((f) => {
    setFeedState(f);
    try { localStorage.setItem(STORAGE.feed, f); } catch { /* noop */ }
  }, []);

  const setFilter = useCallback((f) => {
    setFilterState(f);
    try { localStorage.setItem(STORAGE.filter, f); } catch { /* noop */ }
  }, []);

  const setStream = useCallback((s) => {
    setStreamState(s);
    try { localStorage.setItem(STORAGE.stream, s ? '1' : '0'); } catch { /* noop */ }
  }, []);

  const setStatus = useCallback((s) => setStatusState(s), []);

  const incReq = useCallback(() => {
    reqRef.current++;
    setReqCount(reqRef.current);
  }, []);

  const incErr = useCallback(() => {
    errRef.current++;
    setErrCount(errRef.current);
  }, []);

  const value = {
    dataSource,
    symbol, setSymbol,
    feed, setFeed,
    filter, setFilter,
    stream, setStream,
    status, setStatus,
    reqCount, errCount,
    incReq, incErr,
  };

  return (
    <NewsContext.Provider value={value}>
      {children}
    </NewsContext.Provider>
  );
}

// ================================================================
// useNewsFeed — feed items + pagination + streaming with diff detection
//
// Expects a DataSource adapter (from context) with fetchFeed().
// Your engine is responsible for filtering + normalization.
// ================================================================

import { useCallback, useEffect, useRef, useState } from 'react';
import { PAGE_SIZE, STREAM_INTERVAL } from '../utils/constants';

export function useNewsFeed({ dataSource, feed, symbol, stream, enabled = true, onError }) {
  const [items, setItems]             = useState([]);
  const [page, setPage]               = useState(0);
  const [loading, setLoading]         = useState(false);
  const [error, setError]             = useState(null);
  const [lastUpdate, setLastUpdate]   = useState(null);
  const [pendingNew, setPendingNew]   = useState(0);
  const [nextPollAt, setNextPollAt]   = useState(0);

  const knownIdsRef    = useRef(new Set());
  const loadingRef     = useRef(false);
  const streamTimerRef = useRef(null);
  const flashTimersRef = useRef([]);
  const abortRef       = useRef(null);

  const safeFetch = useCallback(async (pageIdx, signal) => {
    const res = await dataSource.fetchFeed({
      feed,
      symbol: symbol || null,
      page: pageIdx,
      limit: PAGE_SIZE,
      signal,
    });
    return Array.isArray(res) ? res : [];
  }, [dataSource, feed, symbol]);

  const loadNews = useCallback(async ({ append = false } = {}) => {
    if (loadingRef.current || !enabled || !dataSource) return;
    loadingRef.current = true;
    setLoading(true);
    setError(null);

    if (abortRef.current) abortRef.current.abort();
    const ctrl = new AbortController();
    abortRef.current = ctrl;

    const targetPage = append ? page + 1 : 0;

    try {
      const arr = await safeFetch(targetPage, ctrl.signal);

      if (append) {
        setItems((prev) => {
          const seen = new Set(prev.map((p) => p.id));
          const fresh = arr.filter((n) => n && n.id && !seen.has(n.id));
          fresh.forEach((n) => knownIdsRef.current.add(n.id));
          return prev.concat(fresh);
        });
        setPage(targetPage);
      } else {
        knownIdsRef.current = new Set(arr.map((n) => n.id));
        setItems(arr);
        setPage(0);
        setPendingNew(0);
      }

      setLastUpdate(Date.now());
    } catch (err) {
      if (err.name !== 'AbortError') {
        setError(err);
        onError?.(err);
      }
    } finally {
      loadingRef.current = false;
      setLoading(false);
    }
  }, [safeFetch, page, enabled, dataSource, onError]);

  const refresh  = useCallback(() => loadNews({ append: false }), [loadNews]);
  const loadMore = useCallback(() => loadNews({ append: true }),  [loadNews]);

  // Reload when feed or symbol changes
  useEffect(() => {
    if (!enabled) return;
    loadNews({ append: false });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [feed, symbol, enabled]);

  // Streaming tick — diff, prepend, flash
  const streamTick = useCallback(async () => {
    if (!enabled || !dataSource) return;
    try {
      const arr = await safeFetch(0);
      const fresh = arr.filter((n) => n && n.id && !knownIdsRef.current.has(n.id));
      if (fresh.length) {
        fresh.forEach((n) => {
          n._isNew = true;
          knownIdsRef.current.add(n.id);
        });
        setItems((prev) => fresh.concat(prev));
        setPendingNew((n) => n + fresh.length);

        const t = setTimeout(() => {
          setItems((prev) => prev.map((it) => (it._isNew ? { ...it, _isNew: false } : it)));
        }, 2000);
        flashTimersRef.current.push(t);
      }
      setLastUpdate(Date.now());
    } catch (err) {
      // Stay silent on stream errors
      if (err?.name !== 'AbortError') {
        // eslint-disable-next-line no-console
        console.warn('[useNewsFeed stream]', err?.message || err);
      }
    }
  }, [safeFetch, enabled, dataSource]);

  useEffect(() => {
    if (!stream || !enabled) {
      if (streamTimerRef.current) clearInterval(streamTimerRef.current);
      streamTimerRef.current = null;
      setNextPollAt(0);
      return;
    }
    setNextPollAt(Date.now() + STREAM_INTERVAL);
    streamTimerRef.current = setInterval(() => {
      setNextPollAt(Date.now() + STREAM_INTERVAL);
      streamTick();
    }, STREAM_INTERVAL);
    return () => {
      if (streamTimerRef.current) clearInterval(streamTimerRef.current);
      streamTimerRef.current = null;
    };
  }, [stream, enabled, streamTick]);

  useEffect(() => () => {
    flashTimersRef.current.forEach(clearTimeout);
    if (abortRef.current) abortRef.current.abort();
  }, []);

  const clearPendingNew = useCallback(() => setPendingNew(0), []);

  return {
    items,
    loading,
    error,
    lastUpdate,
    pendingNew,
    nextPollAt,
    page,
    refresh,
    loadNews,
    loadMore,
    clearPendingNew,
  };
}

// ================================================================
// TradingOS News — public type contract
//
// Your engine is responsible for filtering and normalizing data.
// The module consumes the shapes defined here. Keep your engine
// output aligned with these interfaces and no internal normalization
// will happen inside the module.
// ================================================================

export type FeedKey = 'stock' | 'general' | 'press' | 'articles';

export type TagKey =
  | 'BREAKING'
  | 'EARNINGS'
  | 'UPGRADE'
  | 'DOWNGRADE'
  | 'M&A'
  | 'SEC'
  | 'GUIDANCE'
  | string;

export type FilterKey = 'ALL' | TagKey;

// ----------------------------------------------------------------
// News item — exactly what the module renders.
// Your engine must return items with this shape.
// ----------------------------------------------------------------
export interface NewsItem {
  /** Stable unique ID. Used for dedup + diff detection during streaming. */
  id: string;

  /** Headline. Plain text. */
  title: string;

  /** Short body / excerpt. Plain text. Optional. */
  text?: string;

  /** Publisher name (e.g. "Reuters", "FMP"). Optional. */
  publisher?: string;

  /** Publish timestamp (ms since epoch). Used for sorting + "time ago". */
  publishedAt: number;

  /** Absolute URL to original article. Optional. */
  url?: string;

  /** Absolute URL to preview image. Optional. */
  image?: string;

  /** Array of ticker symbols mentioned. Used for chips + symbol click. */
  symbols: string[];

  /** Pre-classified tags from your engine. Used for filter pills. */
  tags: TagKey[];

  /** Internal — set by the module when streaming detects a new item. */
  _isNew?: boolean;
}

// ----------------------------------------------------------------
// Quote — single symbol snapshot for QuoteCard.
// ----------------------------------------------------------------
export interface Quote {
  symbol: string;
  name?: string;
  price: number;
  change: number;
  changesPercentage: number;
  dayLow?: number;
  dayHigh?: number;
  yearLow?: number;
  yearHigh?: number;
  open?: number;
  previousClose?: number;
  volume?: number;
  avgVolume?: number;
  marketCap?: number;
  exchange?: string;
  timestamp?: number;
}

// ----------------------------------------------------------------
// TickerItem — one watchlist tile in the ticker tape.
// Map your quotes to this shape inside your dataSource.
// ----------------------------------------------------------------
export interface TickerItem {
  symbol: string;
  price: number;
  change: number;
  changesPercentage: number;
}

// ----------------------------------------------------------------
// SymbolSuggestion — autocomplete result.
// ----------------------------------------------------------------
export interface SymbolSuggestion {
  symbol: string;
  name?: string;
  exchange?: string;
  type?: string;
}

// ----------------------------------------------------------------
// Fetch parameters passed to dataSource methods.
// ----------------------------------------------------------------
export interface FetchFeedParams {
  feed: FeedKey;
  symbol?: string | null;
  page: number;
  limit: number;
  /** AbortSignal — your engine should forward this to fetch(). */
  signal?: AbortSignal;
}

export interface FetchMiniParams {
  kind: 'general' | 'press';
  limit: number;
  signal?: AbortSignal;
}

export interface FetchQuoteParams {
  symbol: string;
  signal?: AbortSignal;
}

export interface FetchTickerParams {
  symbols: string[];
  signal?: AbortSignal;
}

export interface SearchParams {
  query: string;
  limit: number;
  signal?: AbortSignal;
}

// ----------------------------------------------------------------
// DataSource — the ONLY way the module talks to your engine.
//
// All methods return Promises. Reject on failure — the module
// will surface errors to StatusBar and toasts.
//
// Your engine is free to cache, batch, debounce, and route under
// the hood. The module only cares about the shape of the result.
// ----------------------------------------------------------------
export interface DataSource {
  /** Main feed: stock/general/press/articles. */
  fetchFeed(params: FetchFeedParams): Promise<NewsItem[]>;

  /** Small sidebar feeds (MACRO + PRESS). */
  fetchMiniFeed(params: FetchMiniParams): Promise<NewsItem[]>;

  /** Single quote for the selected symbol. */
  fetchQuote(params: FetchQuoteParams): Promise<Quote | null>;

  /** Batch quote for the watchlist ticker tape. */
  fetchTicker(params: FetchTickerParams): Promise<TickerItem[]>;

  /** Autocomplete for the command bar. */
  searchSymbols(params: SearchParams): Promise<SymbolSuggestion[]>;
}

// ----------------------------------------------------------------
// NewsTab public props.
// ----------------------------------------------------------------
export interface NewsTabProps {
  /** Required. Your engine adapter. See DataSource interface. */
  dataSource: DataSource;

  /** Optional render-prop for your chart (e.g. TradingView Lightweight). */
  renderChart?: (ctx: { symbol: string | null }) => React.ReactNode;

  /** Fired when user selects a symbol. Sync with your global state. */
  onSymbolChange?: (symbol: string) => void;

  /** Initial selected symbol. */
  initialSymbol?: string | null;

  /** Initial watchlist override. Defaults to ['AAPL','TSLA','NVDA','SPY','QQQ']. */
  initialWatchlist?: string[];

  /** Initial feed key. Defaults to 'stock'. */
  initialFeed?: FeedKey;

  /** Hide the ChartCard entirely (useful if chart lives outside news tab). */
  hideChart?: boolean;

  /**
   * When true, NewsTab fills the parent (no max-width / centered margin).
   * Use inside the Trading OS News page shell so the terminal uses full center column width.
   */
  fillShell?: boolean;

  /** Custom class on root. */
  className?: string;
}

// ----------------------------------------------------------------
// NewsContext shape (internal — exposed for advanced consumers).
// ----------------------------------------------------------------
export interface NewsContextValue {
  dataSource: DataSource;
  symbol: string | null;
  setSymbol: (sym: string | null) => void;
  feed: FeedKey;
  setFeed: (f: FeedKey) => void;
  filter: FilterKey;
  setFilter: (f: FilterKey) => void;
  stream: boolean;
  setStream: (s: boolean) => void;
  status: 'idle' | 'loading' | 'live' | 'error';
  setStatus: (s: NewsContextValue['status']) => void;
  reqCount: number;
  errCount: number;
  incReq: () => void;
  incErr: () => void;
}

import React, { useMemo, useCallback } from "react";
import styles from "./styles/smart-money.module.css";
import { usePolling } from "./hooks/useAsync";
import { aggregate } from "./engine/aggregator";
import { SignalCard } from "./components/SignalCard";

/**
 * SmartMoneyBanner — full-width thin banner for the top of Intel tab.
 *
 * Props:
 *   dataSource        — SmartMoneyDataSource
 *   refreshMs?        — poll interval, default 30_000 (30s)
 *   onSignalSelect?   — callback when a card is clicked
 *   activeSymbol?     — symbol of the currently focused ticker (highlights card)
 *   config?           — AggregatorConfig overrides
 *   windowHours?      — how far back to pull events, default 48
 */
export function SmartMoneyBanner({
  dataSource,
  refreshMs = 30_000,
  onSignalSelect,
  activeSymbol,
  config,
  windowHours = 48,
}) {
  const fetcher = useCallback(
    (signal) => {
      const since = Date.now() - windowHours * 60 * 60 * 1000;
      return dataSource.listEvents(since, signal);
    },
    [dataSource, windowHours]
  );

  const { data: events, loading, error, refetch } = usePolling(
    fetcher,
    refreshMs,
    [dataSource, windowHours]
  );

  const signals = useMemo(
    () => (events ? aggregate(events, config) : []),
    [events, config]
  );

  return (
    <div className={styles.banner}>
      <div className={styles.bannerHead}>
        <div className={styles.bannerTitleGroup}>
          <span className={styles.bannerDot} data-live={!error ? "true" : undefined} />
          <span className={styles.bannerTitle}>SMART MONEY SIGNALS</span>
          <span className={styles.bannerSub}>
            FUSED · {signals.length} TICKERS · {windowHours}H
          </span>
        </div>
        <button
          type="button"
          className={styles.refreshBtn}
          onClick={refetch}
          disabled={loading}
          title="Refresh now"
        >
          {loading ? "..." : "↻"}
        </button>
      </div>
      <div className={styles.bannerScroller}>
        {error ? (
          <div className={styles.state}>Failed: {String(error.message || error)}</div>
        ) : loading && !events ? (
          <div className={styles.state}>Loading signals...</div>
        ) : signals.length === 0 ? (
          <div className={styles.state}>No signals in the last {windowHours}h.</div>
        ) : (
          signals.map((s) => (
            <SignalCard
              key={s.symbol}
              signal={s}
              active={activeSymbol && s.symbol === activeSymbol.toUpperCase()}
              onClick={onSignalSelect}
            />
          ))
        )}
      </div>
    </div>
  );
}

export default SmartMoneyBanner;

import React, { useMemo, useCallback } from "react";
import styles from "./styles/smart-money.module.css";
import { usePolling } from "./hooks/useAsync";
import { aggregate } from "./engine/aggregator";
import { SignalRow } from "./components/SignalRow";

/**
 * SmartMoneyCompact — small square panel, designed to sit next to a chart.
 *
 * Shows top N signals, optionally filtered to a single symbol (the one the
 * chart is showing) or its peers.
 *
 * Props:
 *   dataSource        — SmartMoneyDataSource
 *   refreshMs?        — poll interval, default 30_000
 *   limit?            — max rows, default 4
 *   filterSymbol?     — show only this ticker + related
 *   onSignalSelect?   — callback when a row is clicked
 *   config?           — AggregatorConfig overrides
 *   windowHours?      — lookback, default 48
 */
export function SmartMoneyCompact({
  dataSource,
  refreshMs = 30_000,
  limit = 4,
  filterSymbol,
  onSignalSelect,
  config,
  windowHours = 48,
}) {
  const fetcher = useCallback(
    (signal) => {
      const since = Date.now() - windowHours * 60 * 60 * 1000;
      return dataSource.listEvents(since, signal);
    },
    [dataSource, windowHours]
  );

  const { data: events, loading, error, refetch } = usePolling(
    fetcher,
    refreshMs,
    [dataSource, windowHours]
  );

  const signals = useMemo(() => {
    if (!events) return [];
    const aggregated = aggregate(events, config);
    if (filterSymbol) {
      const target = filterSymbol.toUpperCase();
      const exact = aggregated.filter((s) => s.symbol === target);
      const rest = aggregated.filter((s) => s.symbol !== target);
      return [...exact, ...rest].slice(0, limit);
    }
    return aggregated.slice(0, limit);
  }, [events, config, filterSymbol, limit]);

  return (
    <div className={styles.compact}>
      <div className={styles.compactHead}>
        <div className={styles.bannerTitleGroup}>
          <span className={styles.bannerDot} data-live={!error ? "true" : undefined} />
          <span className={styles.compactTitle}>
            {filterSymbol ? `SMART MONEY · ${filterSymbol.toUpperCase()}` : "SMART MONEY"}
          </span>
        </div>
        <button
          type="button"
          className={styles.refreshBtn}
          onClick={refetch}
          disabled={loading}
        >
          {loading ? "..." : "↻"}
        </button>
      </div>
      <div className={styles.compactBody}>
        {error ? (
          <div className={styles.state}>Failed to load</div>
        ) : loading && !events ? (
          <div className={styles.state}>Loading...</div>
        ) : signals.length === 0 ? (
          <div className={styles.state}>No signals</div>
        ) : (
          signals.map((s) => (
            <SignalRow key={s.symbol} signal={s} onClick={onSignalSelect} />
          ))
        )}
      </div>
    </div>
  );
}

export default SmartMoneyCompact;

