/**
 * SmartMoney aggregator.
 *
 * Pure function: events -> ranked AggregatedSignal[].
 * No side effects, no I/O. Easy to unit-test.
 *
 * Scoring model:
 *   1. Each event has a base weight per channel.
 *   2. Size multiplier: log10(notionalUsd / 1M) clamped to [0, 2].
 *   3. Time decay: exponential with configurable half-life.
 *   4. Direction sign: bullish +1, bearish -1, neutral 0.
 *   5. Channel diversity bonus: unique channels backing a symbol boost confidence.
 *
 * Final score clamped to [-100, +100].
 */

const DEFAULT_CHANNEL_WEIGHTS = {
  politician: 14,
  insider: 20,
  whale: 12,
  dark_pool: 18,
  options: 22,
  jet: 10,
  vessel: 8,
  news: 6,
};

const DEFAULT_CONFIG = {
  halfLifeHours: 12,
  minNotionalUsd: 50_000,
  maxResults: 20,
};

const HOUR = 1000 * 60 * 60;

function sizeMultiplier(notionalUsd) {
  if (!notionalUsd || notionalUsd <= 0) return 0.5;
  const log = Math.log10(notionalUsd / 1_000_000);
  if (log <= 0) return 0.5;
  return Math.min(2, log + 0.5);
}

function directionSign(d) {
  if (d === "bullish") return 1;
  if (d === "bearish") return -1;
  return 0;
}

function decay(event, now, halfLifeHours) {
  const ageH = (now - event.at) / HOUR;
  if (ageH <= 0) return 1;
  return Math.pow(0.5, ageH / halfLifeHours);
}

function eventContribution(event, now, cfg) {
  const channelWeight =
    (cfg.channelWeights && cfg.channelWeights[event.channel]) ??
    DEFAULT_CHANNEL_WEIGHTS[event.channel] ??
    5;
  const base = event.weight != null ? event.weight * 30 : channelWeight;
  const sign = directionSign(event.direction);
  const size = sizeMultiplier(event.notionalUsd);
  const d = decay(event, now, cfg.halfLifeHours);
  return sign * base * size * d;
}

export function aggregate(events, config = {}) {
  const cfg = {
    ...DEFAULT_CONFIG,
    ...config,
    channelWeights: {
      ...DEFAULT_CHANNEL_WEIGHTS,
      ...(config.channelWeights || {}),
    },
  };
  const now = Date.now();
  const grouped = new Map();

  for (const ev of events) {
    if (!ev.symbol) continue;
    const sym = ev.symbol.toUpperCase();
    if (!grouped.has(sym)) {
      grouped.set(sym, {
        symbol: sym,
        rawScore: 0,
        channels: new Set(),
        totalNotionalUsd: 0,
        reasons: [],
        events: [],
        updatedAt: 0,
      });
    }
    const g = grouped.get(sym);
    g.rawScore += eventContribution(ev, now, cfg);
    g.channels.add(ev.channel);
    g.totalNotionalUsd += ev.notionalUsd || 0;
    g.events.push(ev);
    if (ev.at > g.updatedAt) g.updatedAt = ev.at;
  }

  const signals = [];
  for (const g of grouped.values()) {
    // sort events newest first
    g.events.sort((a, b) => b.at - a.at);

    // diversity bonus: +8 per extra channel beyond first
    const diversityBonus = Math.max(0, g.channels.size - 1) * 8;
    const signed = g.rawScore;
    const adjusted =
      signed >= 0 ? signed + diversityBonus : signed - diversityBonus;
    const score = Math.max(-100, Math.min(100, adjusted));

    // confidence is # of distinct channels, capped at 5
    const confidence = Math.max(1, Math.min(5, g.channels.size));

    const direction =
      score > 5 ? "bullish" : score < -5 ? "bearish" : "neutral";

    const reasons = g.events.slice(0, 5).map((e) => e.headline);

    signals.push({
      symbol: g.symbol,
      score: Math.round(score),
      confidence,
      direction,
      channels: Array.from(g.channels),
      totalNotionalUsd: g.totalNotionalUsd,
      reasons,
      events: g.events,
      updatedAt: g.updatedAt,
    });
  }

  // rank by absolute score, then recency
  signals.sort((a, b) => {
    const diff = Math.abs(b.score) - Math.abs(a.score);
    if (diff !== 0) return diff;
    return b.updatedAt - a.updatedAt;
  });

  return signals.slice(0, cfg.maxResults);
}

export { DEFAULT_CHANNEL_WEIGHTS };

/**
 * SmartMoney — signal engine that aggregates all Intel feeds into one
 * unified score + reason list per ticker.
 *
 * The data source returns RAW events from each channel. The engine in
 * ./engine/aggregator.js fuses them into Signals.
 *
 * Wire your real adapters to:
 *   - Politicians:       https://housestockwatcher.com / Quiver / FMP senate-disclosure
 *   - Insiders:          FMP /v4/insider-trading, Finnhub stock/insider-transactions
 *   - Whales (crypto):   Whale Alert, Arkham, Nansen, on-chain via Supabase
 *   - Dark Pool:         FMP (dark-pool endpoint in ultimate), Unusual Whales
 *   - Unusual Options:   Unusual Whales, CBOE, FMP options flow
 *   - Corporate Jets:    ADS-B Exchange via RapidAPI + your tail-number table
 *   - Vessels:           AIS, MarineTraffic, Kpler
 */

export type SignalChannel =
  | "politician"
  | "insider"
  | "whale"
  | "dark_pool"
  | "options"
  | "jet"
  | "vessel"
  | "news";

export type SignalDirection = "bullish" | "bearish" | "neutral";

export interface SignalEvent {
  id: string;
  channel: SignalChannel;
  symbol: string;                // uppercase ticker or crypto ticker
  direction: SignalDirection;
  notionalUsd?: number;          // dollar size if applicable
  headline: string;              // one-liner
  detail?: string;               // optional longer text
  at: number;                    // epoch ms
  weight?: number;               // 0..1 override; if absent, aggregator computes
  meta?: Record<string, unknown>;
}

export interface AggregatedSignal {
  symbol: string;
  score: number;                  // -100..+100, negative = bearish
  confidence: 1 | 2 | 3 | 4 | 5;  // how many distinct channels contribute
  direction: SignalDirection;
  channels: SignalChannel[];      // distinct channels backing the signal
  totalNotionalUsd: number;
  reasons: string[];              // human-readable bullets, newest first
  events: SignalEvent[];          // raw events used
  updatedAt: number;              // latest event at
}

export interface SmartMoneyDataSource {
  /**
   * Returns a snapshot of recent events across all channels.
   * Implementations can cache and throttle; the component refetches on
   * mount + every refreshMs.
   */
  listEvents(
    sinceMs?: number,
    signal?: AbortSignal
  ): Promise<SignalEvent[]>;
}

export interface AggregatorConfig {
  /** How much each channel weights into the final score (default below). */
  channelWeights?: Partial<Record<SignalChannel, number>>;
  /** Half-life in hours for time decay. Default 12h. */
  halfLifeHours?: number;
  /** Minimum notional to consider non-trivial (USD). Default 50k. */
  minNotionalUsd?: number;
  /** Max signals to return. Default 20. */
  maxResults?: number;
}

import React, { useState, useCallback } from 'react';
import axios from 'axios';
import { Send, Loader2, Sparkles } from 'lucide-react';
import { Button } from './ui/button';
import { ScrollArea } from './ui/scroll-area';
import { getTradingTerminalApiUrl } from '../env';

const AIDesk = ({ symbol, quote, levels, news }) => {
  const API = getTradingTerminalApiUrl();
  const [analysis, setAnalysis] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const getAnalysis = useCallback(async () => {
    if (!symbol || !API) return;

    setLoading(true);
    setError(null);

    try {
      // Build context from available data
      const context = `
        Current price: ${quote?.price || 'N/A'}
        Change: ${quote?.change_percent?.toFixed(2) || 'N/A'}%
        Day High: ${quote?.day_high || 'N/A'}
        Day Low: ${quote?.day_low || 'N/A'}
        Key Levels: ${levels?.slice(0, 3).map(l => `${l.type}: ${l.price}`).join(', ') || 'N/A'}
        Recent News Sentiment: ${news?.slice(0, 3).map(n => n.sentiment).join(', ') || 'N/A'}
      `.trim();

      const response = await axios.post(`${API}/ai/analyze`, {
        symbol: symbol,
        context: context,
        analysis_type: 'sentiment'
      });

      setAnalysis(response.data);
    } catch (err) {
      console.error('Error getting AI analysis:', err);
      setError('Failed to get AI analysis. Please try again.');
    } finally {
      setLoading(false);
    }
  }, [symbol, quote, levels, news, API]);

  const getSentimentClass = (sentiment) => {
    switch (sentiment) {
      case 'bullish':
        return 'sentiment-bullish';
      case 'bearish':
        return 'sentiment-bearish';
      default:
        return 'sentiment-neutral';
    }
  };

  return (
    <div className="flex-1 flex flex-col min-h-0" data-testid="ai-desk">
      <ScrollArea className="flex-1">
        <div className="p-4">
          {!analysis && !loading && !error && (
            <div className="text-center py-8">
              <Sparkles className="w-8 h-8 text-[#3B82F6] mx-auto mb-3 opacity-50" />
              <p className="text-slate-400 text-sm mb-4">
                Get AI-powered analysis for {symbol || 'your selected pair'}
              </p>
              <Button 
                onClick={getAnalysis}
                disabled={!symbol}
                className="bg-[#3B82F6] hover:bg-[#2563EB]"
                data-testid="ai-analyze-button"
              >
                <Sparkles className="w-4 h-4 mr-2" />
                Analyze Now
              </Button>
            </div>
          )}

          {loading && (
            <div className="flex flex-col items-center justify-center py-8">
              <Loader2 className="w-8 h-8 text-[#3B82F6] animate-spin mb-3" />
              <p className="text-slate-400 text-sm">Analyzing {symbol}...</p>
            </div>
          )}

          {error && (
            <div className="text-center py-8">
              <p className="text-[#FF3B30] text-sm mb-4">{error}</p>
              <Button 
                onClick={getAnalysis}
                variant="outline"
                className="border-white/10"
                data-testid="ai-retry-button"
              >
                Try Again
              </Button>
            </div>
          )}

          {analysis && !loading && (
            <div className="space-y-4 animate-fade-in" data-testid="ai-analysis-result">
              {/* Sentiment Badge */}
              <div className="flex items-center justify-between">
                <span className={`px-2 py-1 rounded text-xs font-bold uppercase ${getSentimentClass(analysis.sentiment)}`}>
                  {analysis.sentiment}
                </span>
                <span className="text-xs text-slate-500 font-mono">
                  {Math.round(analysis.confidence * 100)}% confidence
                </span>
              </div>

              {/* Key Points */}
              {analysis.key_points?.length > 0 && (
                <div className="space-y-2">
                  <h5 className="text-xs font-semibold text-slate-400 uppercase tracking-wider">Key Points</h5>
                  <ul className="space-y-1.5">
                    {analysis.key_points.slice(0, 5).map((point, index) => (
                      <li 
                        key={index} 
                        className="text-xs text-slate-300 pl-3 border-l-2 border-[#3B82F6]/30"
                      >
                        {point}
                      </li>
                    ))}
                  </ul>
                </div>
              )}

              {/* Full Analysis */}
              <div className="space-y-2">
                <h5 className="text-xs font-semibold text-slate-400 uppercase tracking-wider">Analysis</h5>
                <p className="text-xs text-slate-300 leading-relaxed whitespace-pre-wrap">
                  {analysis.analysis}
                </p>
              </div>

              {/* Refresh Button */}
              <Button 
                onClick={getAnalysis}
                variant="ghost"
                size="sm"
                className="w-full text-slate-400 hover:text-white mt-4"
                data-testid="ai-refresh-button"
              >
                <Send className="w-3 h-3 mr-2" />
                Get Fresh Analysis
              </Button>
            </div>
          )}
        </div>
      </ScrollArea>
    </div>
  );
};

export default AIDesk;

import React, { useState, useCallback, useEffect } from 'react';
import axios from 'axios';
import { Bell, BellRing, Plus, Trash2, X, ChevronUp, ChevronDown, Volume2 } from 'lucide-react';
import { Button } from './ui/button';
import { ScrollArea } from './ui/scroll-area';
import { getTradingTerminalApiUrl } from '../env';

const AlertPanel = ({ symbol, currentPrice, isOpen, onClose, triggeredAlerts, setTriggeredAlerts }) => {
  const API = getTradingTerminalApiUrl();
  const restAlertsEnabled = Boolean(API);
  const [alerts, setAlerts] = useState([]);
  const [newPrice, setNewPrice] = useState('');
  const [newCondition, setNewCondition] = useState('above');
  const [loading, setLoading] = useState(false);

  const fetchAlerts = useCallback(async () => {
    if (!API) {
      setAlerts([]);
      return;
    }
    try {
      const url = symbol ? `${API}/alerts?symbol=${symbol}` : `${API}/alerts`;
      const response = await axios.get(url);
      setAlerts(response.data);
    } catch (err) {
      console.error('Error fetching alerts:', err);
    }
  }, [symbol, API]);

  useEffect(() => {
    if (isOpen) fetchAlerts();
  }, [isOpen, fetchAlerts]);

  const createAlert = useCallback(async () => {
    if (!API || !newPrice || !symbol) return;
    setLoading(true);
    try {
      await axios.post(`${API}/alerts`, {
        symbol,
        price: parseFloat(newPrice),
        condition: newCondition,
      });
      setNewPrice('');
      await fetchAlerts();
    } catch (err) {
      console.error('Error creating alert:', err);
    } finally {
      setLoading(false);
    }
  }, [newPrice, newCondition, symbol, fetchAlerts, API]);

  const deleteAlert = useCallback(async (alertId) => {
    if (!API) return;
    try {
      await axios.delete(`${API}/alerts/${alertId}`);
      await fetchAlerts();
    } catch (err) {
      console.error('Error deleting alert:', err);
    }
  }, [fetchAlerts, API]);

  const dismissTriggered = useCallback((alertId) => {
    setTriggeredAlerts(prev => prev.filter(a => a.alert_id !== alertId));
  }, [setTriggeredAlerts]);

  if (!isOpen) return null;

  return (
    <div className="absolute right-0 top-full mt-2 z-50 w-80 glass-panel shadow-2xl animate-fade-in" data-testid="alert-panel">
      {/* Header */}
      <div className="p-3 border-b border-white/10 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Bell className="w-4 h-4 text-[#F59E0B]" />
          <span className="font-heading font-medium text-sm">Price Alerts</span>
          <span className="text-[10px] font-mono text-slate-500">{symbol}</span>
        </div>
        <button onClick={onClose} className="text-slate-500 hover:text-white" data-testid="alert-panel-close">
          <X className="w-4 h-4" />
        </button>
      </div>

      {!restAlertsEnabled ? (
        <div className="px-3 py-2 border-b border-amber-500/20 bg-amber-500/10 text-[10px] text-amber-200/90 leading-snug">
          Price alerts (create/list/delete) need <span className="font-mono text-amber-100/90">VITE_TRADING_TERMINAL_API_URL</span> (legacy terminal API).
          Triggered alerts from the chart WebSocket still show above when the Python backend pushes them.
        </div>
      ) : null}

      {/* Triggered alerts */}
      {triggeredAlerts?.length > 0 && (
        <div className="p-2 border-b border-white/10 space-y-1">
          {triggeredAlerts.map((ta, i) => (
            <div key={i} className="flex items-center justify-between p-2 rounded-md bg-[#F59E0B]/10 border border-[#F59E0B]/20 animate-fade-in" data-testid={`triggered-alert-${i}`}>
              <div className="flex items-center gap-2">
                <BellRing className="w-4 h-4 text-[#F59E0B] animate-pulse" />
                <div>
                  <p className="text-xs text-[#F59E0B] font-medium">{ta.label}</p>
                  <p className="text-[10px] text-slate-400 font-mono">Hit at {ta.price?.toFixed(4)}</p>
                </div>
              </div>
              <button onClick={() => dismissTriggered(ta.alert_id)} className="text-slate-500 hover:text-white">
                <X className="w-3 h-3" />
              </button>
            </div>
          ))}
        </div>
      )}

      {/* Create alert */}
      <div className={`p-3 border-b border-white/10 ${restAlertsEnabled ? '' : 'opacity-40 pointer-events-none'}`}>
        <div className="flex items-center gap-2">
          <div className="flex items-center border border-white/10 rounded-md overflow-hidden">
            <button
              onClick={() => setNewCondition('above')}
              className={`px-2 py-1.5 text-[10px] font-bold uppercase flex items-center gap-1 transition-all ${
                newCondition === 'above' ? 'bg-[#00E676]/20 text-[#00E676]' : 'text-slate-500 hover:text-white'
              }`}
              data-testid="alert-condition-above"
            >
              <ChevronUp className="w-3 h-3" />
            </button>
            <button
              onClick={() => setNewCondition('below')}
              className={`px-2 py-1.5 text-[10px] font-bold uppercase flex items-center gap-1 transition-all ${
                newCondition === 'below' ? 'bg-[#FF3B30]/20 text-[#FF3B30]' : 'text-slate-500 hover:text-white'
              }`}
              data-testid="alert-condition-below"
            >
              <ChevronDown className="w-3 h-3" />
            </button>
          </div>
          <input
            type="number"
            step="any"
            value={newPrice}
            onChange={e => setNewPrice(e.target.value)}
            placeholder={currentPrice?.toFixed(4) || 'Price'}
            className="flex-1 bg-white/5 border border-white/10 rounded-md px-2 py-1.5 text-xs font-mono text-white placeholder-slate-600 focus:outline-none focus:border-[#3B82F6]/50"
            onKeyDown={e => e.key === 'Enter' && createAlert()}
            data-testid="alert-price-input"
          />
          <Button
            size="sm"
            onClick={createAlert}
            disabled={loading || !newPrice}
            className="bg-[#3B82F6] hover:bg-[#2563EB] h-8 px-3"
            data-testid="alert-create-button"
          >
            <Plus className="w-3 h-3" />
          </Button>
        </div>
      </div>

      {/* Active alerts list */}
      <ScrollArea className="max-h-48">
        <div className="p-2 space-y-1">
          {alerts.length === 0 ? (
            <p className="text-center text-slate-600 text-xs py-4">
              {restAlertsEnabled ? `No active alerts for ${symbol}` : 'REST API disabled — configure terminal URL to manage saved alerts.'}
            </p>
          ) : (
            alerts.map(alert => (
              <div
                key={alert.id}
                className={`flex items-center justify-between p-2 rounded-md transition-colors ${
                  alert.triggered ? 'bg-white/5 opacity-50' : 'hover:bg-white/[0.03]'
                }`}
                data-testid={`alert-item-${alert.id}`}
              >
                <div className="flex items-center gap-2">
                  <div className={`w-1.5 h-1.5 rounded-full ${
                    alert.condition === 'above' ? 'bg-[#00E676]' : 'bg-[#FF3B30]'
                  }`} />
                  <div>
                    <p className="text-xs font-mono text-white">
                      {alert.condition === 'above' ? '>' : '<'} {alert.price?.toFixed(4)}
                    </p>
                    {alert.label && (
                      <p className="text-[10px] text-slate-500 truncate max-w-[160px]">{alert.label}</p>
                    )}
                  </div>
                </div>
                <button
                  onClick={() => deleteAlert(alert.id)}
                  className="text-slate-600 hover:text-[#FF3B30] transition-colors"
                  data-testid={`alert-delete-${alert.id}`}
                >
                  <Trash2 className="w-3 h-3" />
                </button>
              </div>
            ))
          )}
        </div>
      </ScrollArea>
    </div>
  );
};

export default AlertPanel;

