import React, { useState, useEffect, useMemo } from 'react';
import { BarChart3, Clock } from 'lucide-react';

const OrderBook = ({ quote, symbol }) => {
  const [activeTab, setActiveTab] = useState('book');

  // Generate simulated order book data based on current price
  const { asks, bids } = useMemo(() => {
    if (!quote?.price) return { asks: [], bids: [] };
    const price = quote.price;
    const dec = price < 10 ? 5 : 2;
    const step = price < 10 ? 0.0005 : 0.5;

    const askRows = [];
    const bidRows = [];
    let cumAsk = 0;
    let cumBid = 0;

    for (let i = 0; i < 8; i++) {
      const askPrice = price + step * (i + 1);
      const bidPrice = price - step * (i + 1);
      const askSize = Math.floor(Math.random() * 400 + 50);
      const bidSize = Math.floor(Math.random() * 400 + 50);
      cumAsk += askSize;
      cumBid += bidSize;

      askRows.push({ price: askPrice.toFixed(dec), size: askSize, total: cumAsk });
      bidRows.push({ price: bidPrice.toFixed(dec), size: bidSize, total: cumBid });
    }
    return { asks: askRows.reverse(), bids: bidRows };
  }, [quote?.price]);

  // Simulated recent trades
  const trades = useMemo(() => {
    if (!quote?.price) return [];
    const price = quote.price;
    const dec = price < 10 ? 5 : 2;
    const step = price < 10 ? 0.0003 : 0.3;
    return Array.from({ length: 10 }, (_, i) => ({
      price: (price + (Math.random() - 0.5) * step * 4).toFixed(dec),
      size: Math.floor(Math.random() * 200 + 10),
      side: Math.random() > 0.5 ? 'buy' : 'sell',
      time: new Date(Date.now() - i * 3000).toLocaleTimeString('en-US', { hour12: false }),
    }));
  }, [quote?.price]);

  const maxTotal = Math.max(...bids.map(b => b.total), ...asks.map(a => a.total), 1);

  return (
    <div className="glass-panel flex flex-col h-full min-h-0" data-testid="order-book">
      {/* Header tabs */}
      <div className="flex items-center border-b border-white/[0.04]">
        <button
          onClick={() => setActiveTab('book')}
          className={`flex items-center gap-1.5 px-4 py-2.5 text-[10px] font-semibold uppercase tracking-wider transition-all ${
            activeTab === 'book' ? 'text-white border-b-2 border-[#06b6d4]' : 'text-white/35 hover:text-white/60'
          }`}
          data-testid="orderbook-tab"
        >
          <BarChart3 className="w-3 h-3" />
          Order Book
        </button>
        <button
          onClick={() => setActiveTab('trades')}
          className={`flex items-center gap-1.5 px-4 py-2.5 text-[10px] font-semibold uppercase tracking-wider transition-all ${
            activeTab === 'trades' ? 'text-white border-b-2 border-[#06b6d4]' : 'text-white/35 hover:text-white/60'
          }`}
          data-testid="trades-tab"
        >
          <Clock className="w-3 h-3" />
          Trades
        </button>
      </div>

      {activeTab === 'book' ? (
        <div className="flex-1 overflow-hidden flex flex-col">
          {/* Column headers */}
          <div className="flex items-center justify-between px-3 py-1.5 text-[8px] uppercase tracking-widest text-white/25 font-semibold border-b border-white/[0.04]">
            <span>Price</span>
            <span>Size</span>
            <span>Total</span>
          </div>

          {/* Asks (sells) */}
          <div className="flex-1 overflow-y-auto">
            {asks.map((row, i) => (
              <div key={`ask-${i}`} className="relative flex items-center justify-between px-3 py-1 text-[11px] font-mono">
                <div className="absolute right-0 top-0 bottom-0 bg-[#ef4444]/10" style={{ width: `${(row.total / maxTotal) * 100}%` }} />
                <span className="text-[#ef4444] relative z-10">{row.price}</span>
                <span className="text-white/50 relative z-10">{row.size}</span>
                <span className="text-white/30 relative z-10">{row.total}</span>
              </div>
            ))}
          </div>

          {/* Current price */}
          <div className="px-3 py-2 text-center border-y border-white/[0.04] bg-white/[0.02]">
            <span className="font-mono text-base font-bold text-[#06b6d4]">
              {quote?.price?.toFixed(quote.price < 10 ? 5 : 2)}
            </span>
          </div>

          {/* Bids (buys) */}
          <div className="flex-1 overflow-y-auto">
            {bids.map((row, i) => (
              <div key={`bid-${i}`} className="relative flex items-center justify-between px-3 py-1 text-[11px] font-mono">
                <div className="absolute right-0 top-0 bottom-0 bg-[#22c55e]/10" style={{ width: `${(row.total / maxTotal) * 100}%` }} />
                <span className="text-[#22c55e] relative z-10">{row.price}</span>
                <span className="text-white/50 relative z-10">{row.size}</span>
                <span className="text-white/30 relative z-10">{row.total}</span>
              </div>
            ))}
          </div>
        </div>
      ) : (
        <div className="flex-1 overflow-y-auto">
          <div className="flex items-center justify-between px-3 py-1.5 text-[8px] uppercase tracking-widest text-white/25 font-semibold border-b border-white/[0.04]">
            <span>Price</span>
            <span>Size</span>
            <span>Time</span>
          </div>
          {trades.map((trade, i) => (
            <div key={i} className="flex items-center justify-between px-3 py-1 text-[11px] font-mono">
              <span className={trade.side === 'buy' ? 'text-[#22c55e]' : 'text-[#ef4444]'}>{trade.price}</span>
              <span className="text-white/50">{trade.size}</span>
              <span className="text-white/25">{trade.time}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default OrderBook;

import React, { useState, useCallback } from 'react';
import axios from 'axios';
import { Calculator, X } from 'lucide-react';
import { Button } from './ui/button';
import { getTradingTerminalApiUrl } from '../env';

const PositionCalculator = ({ isOpen, onClose, symbol, currentPrice }) => {
  const API = getTradingTerminalApiUrl();
  const [accountSize, setAccountSize] = useState('10000');
  const [riskPercent, setRiskPercent] = useState('1');
  const [entryPrice, setEntryPrice] = useState(currentPrice?.toFixed(4) || '');
  const [stopLoss, setStopLoss] = useState('');
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);

  const calculate = useCallback(async () => {
    if (!entryPrice || !stopLoss) return;
    setLoading(true);
    try {
      const res = await axios.post(`${API}/calculator/position`, {
        account_size: parseFloat(accountSize),
        risk_percent: parseFloat(riskPercent),
        entry_price: parseFloat(entryPrice),
        stop_loss: parseFloat(stopLoss),
        symbol,
      });
      setResult(res.data);
    } catch (err) {
      console.error('Calculator error:', err);
    } finally {
      setLoading(false);
    }
  }, [accountSize, riskPercent, entryPrice, stopLoss, symbol, API]);

  if (!isOpen) return null;

  return (
    <div className="absolute left-0 bottom-full mb-2 z-50 w-72 glass-panel shadow-2xl animate-fade-in" data-testid="position-calculator">
      <div className="p-3 border-b border-white/10 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Calculator className="w-4 h-4 text-[#3B82F6]" />
          <span className="font-heading font-medium text-sm">Position Calculator</span>
        </div>
        <button onClick={onClose} className="text-slate-500 hover:text-white" data-testid="calc-close">
          <X className="w-4 h-4" />
        </button>
      </div>

      <div className="p-3 space-y-3">
        <div className="grid grid-cols-2 gap-2">
          <div>
            <label className="text-[10px] text-slate-500 uppercase">Account Size</label>
            <input value={accountSize} onChange={e => setAccountSize(e.target.value)} className="w-full bg-white/5 border border-white/10 rounded px-2 py-1.5 text-xs font-mono text-white focus:outline-none focus:border-[#3B82F6]/50" data-testid="calc-account" />
          </div>
          <div>
            <label className="text-[10px] text-slate-500 uppercase">Risk %</label>
            <input value={riskPercent} onChange={e => setRiskPercent(e.target.value)} className="w-full bg-white/5 border border-white/10 rounded px-2 py-1.5 text-xs font-mono text-white focus:outline-none focus:border-[#3B82F6]/50" data-testid="calc-risk" />
          </div>
          <div>
            <label className="text-[10px] text-slate-500 uppercase">Entry Price</label>
            <input value={entryPrice} onChange={e => setEntryPrice(e.target.value)} placeholder={currentPrice?.toFixed(4)} className="w-full bg-white/5 border border-white/10 rounded px-2 py-1.5 text-xs font-mono text-white placeholder-slate-700 focus:outline-none focus:border-[#3B82F6]/50" data-testid="calc-entry" />
          </div>
          <div>
            <label className="text-[10px] text-slate-500 uppercase">Stop Loss</label>
            <input value={stopLoss} onChange={e => setStopLoss(e.target.value)} className="w-full bg-white/5 border border-white/10 rounded px-2 py-1.5 text-xs font-mono text-white focus:outline-none focus:border-[#3B82F6]/50" data-testid="calc-sl" />
          </div>
        </div>

        <Button onClick={calculate} disabled={loading} className="w-full bg-[#3B82F6] hover:bg-[#2563EB] h-8 text-xs" data-testid="calc-button">
          Calculate
        </Button>

        {result && (
          <div className="space-y-2 pt-2 border-t border-white/10 animate-fade-in" data-testid="calc-result">
            <div className="flex justify-between">
              <span className="text-[10px] text-slate-400">Lot Size</span>
              <span className="text-sm font-mono text-white font-bold">{result.lot_size}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-[10px] text-slate-400">Risk Amount</span>
              <span className="text-xs font-mono text-[#FF3B30]">${result.risk_amount}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-[10px] text-slate-400">Stop Distance</span>
              <span className="text-xs font-mono text-slate-300">{result.stop_pips} pips</span>
            </div>
            <div className="flex justify-between">
              <span className="text-[10px] text-slate-400">TP 1R</span>
              <span className="text-xs font-mono text-[#00E676]">{result.reward_1r}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-[10px] text-slate-400">TP 2R</span>
              <span className="text-xs font-mono text-[#00E676]">{result.reward_2r}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-[10px] text-slate-400">TP 3R</span>
              <span className="text-xs font-mono text-[#00E676]">{result.reward_3r}</span>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default PositionCalculator;

import React from 'react';
import { TrendingUp, TrendingDown } from 'lucide-react';

const PriceInfoBar = ({ quote, symbol }) => {
  if (!quote) return null;

  const isPositive = quote.change_percent >= 0;
  const sentiment = quote.change_percent > 0.5 ? 'Bullish' : quote.change_percent < -0.5 ? 'Bearish' : 'Neutral';
  const sentimentColor = sentiment === 'Bullish' ? 'bg-[#00E676]/20 text-[#00E676]' : sentiment === 'Bearish' ? 'bg-[#FF3B30]/20 text-[#FF3B30]' : 'bg-white/10 text-slate-400';
  const dec = quote.price < 10 ? 4 : 2;
  const spread = quote.day_high && quote.day_low ? ((quote.day_high - quote.day_low) / quote.price * 100).toFixed(3) : '—';

  return (
    <div className="flex items-center justify-between px-3 py-0.5 border-b border-white/[0.03]" data-testid="price-info-bar">
      {/* Left: Price + Sentiment */}
      <div className="flex items-center gap-3">
        <span className="font-mono text-base font-bold text-white">{quote.price?.toFixed(dec)}</span>
        <span className={`font-mono text-xs ${isPositive ? 'text-[#00E676]' : 'text-[#FF3B30]'}`}>
          {isPositive ? '+' : ''}{quote.change_percent?.toFixed(2)}%
        </span>
        <span className={`px-1.5 py-0.5 rounded text-[9px] font-bold uppercase ${sentimentColor}`}>
          {sentiment === 'Bullish' && <TrendingUp className="w-2.5 h-2.5 inline mr-0.5" />}
          {sentiment === 'Bearish' && <TrendingDown className="w-2.5 h-2.5 inline mr-0.5" />}
          {sentiment}
        </span>
      </div>

      {/* Right: OHLC data */}
      <div className="flex items-center gap-4 text-[10px] font-mono">
        {quote.open_price && (
          <span className="text-slate-500">O <span className="text-slate-300">{quote.open_price?.toFixed(dec)}</span></span>
        )}
        <span className="text-slate-500">H <span className="text-[#00E676]">{quote.day_high?.toFixed(dec)}</span></span>
        <span className="text-slate-500">L <span className="text-[#FF3B30]">{quote.day_low?.toFixed(dec)}</span></span>
        {quote.volume && (
          <span className="text-slate-500">Vol <span className="text-slate-300">{(quote.volume / 1000000).toFixed(1)}M</span></span>
        )}
        <span className="text-slate-500">Spread <span className="text-slate-300">{spread}%</span></span>
      </div>
    </div>
  );
};

