"use client";
// Inspired by react-hot-toast library
import * as React from "react"

const TOAST_LIMIT = 1
const TOAST_REMOVE_DELAY = 1000000

const actionTypes = {
  ADD_TOAST: "ADD_TOAST",
  UPDATE_TOAST: "UPDATE_TOAST",
  DISMISS_TOAST: "DISMISS_TOAST",
  REMOVE_TOAST: "REMOVE_TOAST"
}

let count = 0

function genId() {
  count = (count + 1) % Number.MAX_SAFE_INTEGER
  return count.toString();
}

const toastTimeouts = new Map()

const addToRemoveQueue = (toastId) => {
  if (toastTimeouts.has(toastId)) {
    return
  }

  const timeout = setTimeout(() => {
    toastTimeouts.delete(toastId)
    dispatch({
      type: "REMOVE_TOAST",
      toastId: toastId,
    })
  }, TOAST_REMOVE_DELAY)

  toastTimeouts.set(toastId, timeout)
}

export const reducer = (state, action) => {
  switch (action.type) {
    case "ADD_TOAST":
      return {
        ...state,
        toasts: [action.toast, ...state.toasts].slice(0, TOAST_LIMIT),
      };

    case "UPDATE_TOAST":
      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === action.toast.id ? { ...t, ...action.toast } : t),
      };

    case "DISMISS_TOAST": {
      const { toastId } = action

      // ! Side effects ! - This could be extracted into a dismissToast() action,
      // but I'll keep it here for simplicity
      if (toastId) {
        addToRemoveQueue(toastId)
      } else {
        state.toasts.forEach((toast) => {
          addToRemoveQueue(toast.id)
        })
      }

      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === toastId || toastId === undefined
            ? {
                ...t,
                open: false,
              }
            : t),
      };
    }
    case "REMOVE_TOAST":
      if (action.toastId === undefined) {
        return {
          ...state,
          toasts: [],
        }
      }
      return {
        ...state,
        toasts: state.toasts.filter((t) => t.id !== action.toastId),
      };
  }
}

const listeners = []

let memoryState = { toasts: [] }

function dispatch(action) {
  memoryState = reducer(memoryState, action)
  listeners.forEach((listener) => {
    listener(memoryState)
  })
}

function toast({
  ...props
}) {
  const id = genId()

  const update = (props) =>
    dispatch({
      type: "UPDATE_TOAST",
      toast: { ...props, id },
    })
  const dismiss = () => dispatch({ type: "DISMISS_TOAST", toastId: id })

  dispatch({
    type: "ADD_TOAST",
    toast: {
      ...props,
      id,
      open: true,
      onOpenChange: (open) => {
        if (!open) dismiss()
      },
    },
  })

  return {
    id: id,
    dismiss,
    update,
  }
}

function useToast() {
  const [state, setState] = React.useState(memoryState)

  React.useEffect(() => {
    listeners.push(setState)
    return () => {
      const index = listeners.indexOf(setState)
      if (index > -1) {
        listeners.splice(index, 1)
      }
    };
  }, [state])

  return {
    ...state,
    toast,
    dismiss: (toastId) => dispatch({ type: "DISMISS_TOAST", toastId }),
  };
}

export { useToast, toast }

export type ToastInput = {
  title?: string;
  description?: string;
  durationMs?: number;
};

type ToastItem = ToastInput & {
  id: string;
  createdAt: number;
};

const listeners = new Set<(items: ToastItem[]) => void>();
let items: ToastItem[] = [];

function emit() {
  for (const cb of listeners) cb(items);
}

export function subscribeToToasts(cb: (items: ToastItem[]) => void) {
  listeners.add(cb);
  cb(items);
  return () => {
    listeners.delete(cb);
  };
}

export function dismissToast(id: string) {
  items = items.filter((t) => t.id !== id);
  emit();
}

export function toast(input: ToastInput) {
  const id = `${Date.now()}_${Math.random().toString(16).slice(2)}`;
  const t: ToastItem = { id, createdAt: Date.now(), ...input };
  items = [t, ...items].slice(0, 5);
  emit();

  const duration = Math.max(800, input.durationMs ?? 3200);
  window.setTimeout(() => dismissToast(id), duration);
}

import { createContext, useCallback, useContext, useMemo, useState, type ReactNode } from 'react';
import { BookOpen, ChevronDown } from 'lucide-react';

interface BeginnerModeCtx {
  beginner: boolean;
  toggle: () => void;
  setBeginner: (next: boolean) => void;
}

const BeginnerContext = createContext<BeginnerModeCtx>({
  beginner: false,
  toggle: () => {},
  setBeginner: () => {},
});

export function BeginnerModeProvider({ children }: { children: ReactNode }) {
  const [beginner, setBeginnerState] = useState(() => {
    try {
      return localStorage.getItem('tos_beginner') === '1';
    } catch {
      return false;
    }
  });

  const setBeginner = useCallback((next: boolean) => {
    setBeginnerState(() => {
      try {
        localStorage.setItem('tos_beginner', next ? '1' : '0');
      } catch {
        /* ignore */
      }
      return next;
    });
  }, []);

  const toggle = useCallback(() => {
    setBeginner(!beginner);
  }, [beginner, setBeginner]);

  const value = useMemo(() => ({ beginner, toggle, setBeginner }), [beginner, toggle, setBeginner]);

  return <BeginnerContext.Provider value={value}>{children}</BeginnerContext.Provider>;
}

export function useBeginner() {
  return useContext(BeginnerContext);
}

export const WIDGET_LABELS: Record<string, { short: string; full: string; hint: string }> = {
  heatmap: {
    short: 'Heatmap',
    full: 'Market Heatmaps',
    hint:
      "Visual overviews that instantly show which markets are hot (moving a lot) and which are cold (barely moving).\n\nMarket tab: Colored squares for each symbol — green = up today, red = down. Bigger % move = stronger color.\nTreemap tab: Tiles sized by market cap weight. Bright green/red shows leaders/laggards.\nLiquidity tab: Shows bid/ask depth near the current price.\n\nHow to use it: Scan the heatmap each morning before trading. If a whole sector is red, that's macro risk. If one symbol is bright green in a sea of red, it's showing relative strength.",
  },
};

export function useWidgetLabel(key: string) {
  const { beginner } = useBeginner();
  const entry = WIDGET_LABELS[key];
  if (!entry) return { title: key, hint: undefined as string | undefined };
  return {
    title: beginner ? entry.full : entry.short,
    hint: beginner ? entry.hint : undefined,
  };
}

export function PageBeginnerBanner({ widgetKey }: { widgetKey: string }) {
  const { beginner } = useBeginner();
  const [collapsed, setCollapsed] = useState(false);
  const entry = WIDGET_LABELS[widgetKey];
  if (!beginner || !entry) return null;
  const paragraphs = entry.hint.split('\n\n').filter(Boolean);
  return (
    <div className="shrink-0 border-b border-blue-500/[0.12] bg-blue-950/[0.18] animate-in fade-in-0 slide-in-from-top-1 duration-200">
      <div className="flex items-center justify-between px-3 py-1.5">
        <div className="flex items-center gap-1.5">
          <BookOpen className="h-3 w-3 text-blue-400/50 shrink-0" />
          <span className="text-[9px] font-bold text-blue-400/60 uppercase tracking-widest">
            How to use · {entry.full}
          </span>
        </div>
        <button
          onClick={() => setCollapsed((c) => !c)}
          className="text-muted-foreground hover:text-muted-foreground transition-colors"
          aria-label={collapsed ? 'Show explanation' : 'Hide explanation'}
        >
          <ChevronDown className={`h-3 w-3 transition-transform duration-200 ${collapsed ? '-rotate-90' : ''}`} />
        </button>
      </div>
      {!collapsed ? (
        <div className="px-3 pb-2.5 space-y-1.5">
          {paragraphs.map((para, i) => (
            <p
              key={i}
              className={`text-[10px] leading-relaxed ${i === 0 ? 'text-blue-100/50' : 'text-blue-100/35'}`}
            >
              {para}
            </p>
          ))}
        </div>
      ) : null}
    </div>
  );
}

/**
 * ENGINE ADAPTER — public barrel for pages (`@/lib/engineAdapter`).
 *
 * Market data paths call `getTradingAdapter()` (Supabase `engine-proxy` when `VITE_USE_ENGINE_EDGE=true`).
 * Intel snapshots call Supabase `intel-proxy` when Edge mode is on (see `callIntelProxy`).
 * Functions marked PLACEHOLDER in JSDoc have no engine implementation yet — they return deterministic demo data.
 */

import { supabase } from '@/lib/supabase';
import { getTradingAdapter } from './tradingAdapterSingleton';
import type { ChartFetchDebugMeta } from '@/engine/types/chart';
import { ChartFetchError } from '@/engine/types/chart';
import type { CorporateJet, CorporateJetsMetrics } from '@/engine/types/intel';

type IntelFeedKey = 'corporateJets' | 'vesselStream' | 'insiderTrades' | 'whaleTransactions';
const intelFeedLive: Record<IntelFeedKey, boolean> = {
  corporateJets: false,
  vesselStream: false,
  insiderTrades: false,
  whaleTransactions: false,
};

export function isIntelFeedLive(feed: IntelFeedKey): boolean {
  return intelFeedLive[feed] === true;
}

const intelFeedLastOkMs: Record<IntelFeedKey, number> = {
  corporateJets: 0,
  vesselStream: 0,
  insiderTrades: 0,
  whaleTransactions: 0,
};

const intelFeedLastError: Record<IntelFeedKey, string | null> = {
  corporateJets: null,
  vesselStream: null,
  insiderTrades: null,
  whaleTransactions: null,
};

export function getIntelFeedRefreshedSecondsAgo(feed: IntelFeedKey): number | null {
  const ms = intelFeedLastOkMs[feed] || 0;
  if (!ms) return null;
  return Math.max(0, Math.round((Date.now() - ms) / 1000));
}

export function getIntelFeedLastError(feed: IntelFeedKey): string | null {
  return intelFeedLastError[feed] ?? null;
}

/** True when at least one macro series was loaded from the engine (FRED via engine-proxy), not full mock fallback. */
let macroFeedLive = false;
let macroFeedLastOkMs = 0;
let macroFeedLastError: string | null = null;

export function isMacroFeedLive(): boolean {
  return macroFeedLive;
}

export function getMacroFeedRefreshedSecondsAgo(): number | null {
  if (!macroFeedLastOkMs) return null;
  return Math.max(0, Math.round((Date.now() - macroFeedLastOkMs) / 1000));
}

export function getMacroFeedLastError(): string | null {
  return macroFeedLastError;
}

let newsFeedLive = false;
let newsFeedLastOkMs = 0;
let newsFeedLastError: string | null = null;

export function isNewsFeedLive(): boolean {
  return newsFeedLive;
}

export function getNewsFeedRefreshedSecondsAgo(): number | null {
  if (!newsFeedLastOkMs) return null;
  return Math.max(0, Math.round((Date.now() - newsFeedLastOkMs) / 1000));
}

