  const limit = Math.min(120, Math.max(1, options?.limit ?? 50));

  const { value: items, error: newsErr } = await tryEngineDetailed((a) => a.news(symbol, { limit }));
  if (items && Array.isArray(items) && items.length > 0) {
    newsFeedLive = true;
    newsFeedLastOkMs = Date.now();
