    { symbol: 'XAU/USD', price: 2342.00, change24h: 1.85, rsi: 72.5, volumeX: 3.2, klv: '2345.00', sparkline: spark(24, 2320, 15), matchedFilters: ['Volume Spike','Golden Cross'], category: 'Metals' },
