import { useEffect, useMemo, useState } from 'react';
import { isSupabaseConfigured, supabase } from '@/lib/supabase';

export type JetAlertSeverity = 'info' | 'watch' | 'unusual';

export type JetAlert = {
  ticker: string;
  tail_number?: string | null;
  airport_icao?: string | null;
  landed_at?: string | null;
  reason?: string | null;
  severity: JetAlertSeverity;
  expires_at?: string | null;
};

export type JetAlertMap = Record<string, JetAlert>;

function nowIso() {
  return new Date().toISOString();
}

function stubAlerts(): JetAlert[] {
  // Placeholder until Supabase tables + Edge Function are live.
  // Keep small & deterministic so the UI doesn't feel spammy.
  return [
    {
      ticker: 'NVDA',
      tail_number: 'N123NV',
      airport_icao: 'KTEB',
      landed_at: nowIso(),
      reason: 'Unusual landing near NYC',
      severity: 'unusual',
      expires_at: new Date(Date.now() + 30 * 60_000).toISOString(),
    },
  ];
}

function buildMap(rows: JetAlert[]): JetAlertMap {
  const out: JetAlertMap = {};
  for (const r of rows) {
    const t = String(r.ticker || '').toUpperCase().trim();
    if (!t) continue;
    out[t] = { ...r, ticker: t };
  }
  return out;
}

function isExpired(a: JetAlert) {
  if (!a.expires_at) return false;
  const ts = new Date(a.expires_at).getTime();
  return Number.isFinite(ts) ? ts <= Date.now() : false;
}

export function useJetAlerts(pollMs = 60_000): { alerts: JetAlertMap; source: 'supabase' | 'stub' } {
  const [rows, setRows] = useState<JetAlert[]>([]);
  const [source, setSource] = useState<'supabase' | 'stub'>(() =>
    isSupabaseConfigured() ? 'supabase' : 'stub'
  );

  useEffect(() => {
    let alive = true;

    async function loadSupabase() {
      try {
        const { data, error } = await supabase
          .from('jet_alerts')
          .select('ticker, tail_number, airport_icao, landed_at, reason, severity, expires_at')
          .gt('expires_at', new Date().toISOString());
        if (!alive) return;
        if (error) throw error;
        setSource('supabase');
        setRows((data as any[])?.map((d) => ({ ...d, ticker: String(d.ticker || '').toUpperCase() })) ?? []);
      } catch {
        // If Supabase isn't provisioned yet (table missing) we silently fall back to stub.
        if (!alive) return;
        setSource('stub');
        setRows(stubAlerts());
      }
    }

    function load() {
      if (isSupabaseConfigured()) loadSupabase();
      else {
        setSource('stub');
        setRows(stubAlerts());
      }
    }

    load();
    const t = window.setInterval(load, pollMs);
    return () => {
      alive = false;
      window.clearInterval(t);
    };
  }, [pollMs]);

  const alerts = useMemo(() => {
    const filtered = rows.filter((a) => !isExpired(a));
    return buildMap(filtered);
  }, [rows]);

  return { alerts, source };
}

export function jetIconTone(severity: JetAlertSeverity): { fg: string; glow: string } {
  if (severity === 'unusual') return { fg: 'text-cyan-300', glow: 'shadow-[0_0_10px_rgba(34,211,238,0.35)]' };
  if (severity === 'watch') return { fg: 'text-yellow-300', glow: 'shadow-[0_0_10px_rgba(253,224,71,0.28)]' };
  return { fg: 'text-white/40', glow: 'shadow-none' };
}

import type {
  LiveEngineClientMessage,
  LiveEngineMessage,
  SubscribeMessage,
  UnsubscribeMessage,
} from './liveEngineTypes';

type SubscriptionKey = `${string}__${string}`; // symbol__timeframe

function keyOf(symbol: string, timeframe: string): SubscriptionKey {
  return `${symbol}__${timeframe}`;
}

function nowIso(): string {
  return new Date().toISOString();
}

export interface LiveEngineClientOptions {
  /** e.g. wss://<worker-domain>/ws */
  url: string;
  /** max outbound message rate to UI (ms). */
  uiThrottleMs?: number;
  /** reconnect backoff cap. */
  maxReconnectMs?: number;
}

export class LiveEngineClient {
  private url: string;
  private ws: WebSocket | null = null;
  private reconnectTimer: number | null = null;
  private reconnectAttempt = 0;
  private readonly maxReconnectMs: number;

  private readonly subscriptions = new Set<SubscriptionKey>();
  private listeners = new Set<(msg: LiveEngineMessage) => void>();

  // UI throttling (batch dispatch)
  private readonly uiThrottleMs: number;
  private pending: LiveEngineMessage[] = [];
  private flushTimer: number | null = null;

  constructor(opts: LiveEngineClientOptions) {
    this.url = opts.url;
    this.uiThrottleMs = Math.max(20, opts.uiThrottleMs ?? 75);
    this.maxReconnectMs = Math.max(1000, opts.maxReconnectMs ?? 15_000);
  }

  onMessage(cb: (msg: LiveEngineMessage) => void): () => void {
    this.listeners.add(cb);
    return () => this.listeners.delete(cb);
  }

  connect(): void {
    if (this.ws && (this.ws.readyState === WebSocket.OPEN || this.ws.readyState === WebSocket.CONNECTING)) return;
    this.clearReconnect();

    const ws = new WebSocket(this.url);
    this.ws = ws;

    ws.onopen = () => {
      this.reconnectAttempt = 0;
      // Resubscribe everything
      for (const sub of this.subscriptions) {
        const [symbol, timeframe] = sub.split('__');
        this.send({ type: 'subscribe', symbol, timeframe } satisfies SubscribeMessage);
      }
      this.send({ type: 'ping', ts: nowIso() });
    };

    ws.onmessage = (evt) => {
      let msg: unknown;
      try {
        msg = JSON.parse(String(evt.data));
      } catch {
        return;
      }
      this.enqueue(msg as LiveEngineMessage);
    };

    ws.onclose = () => {
      this.ws = null;
      this.scheduleReconnect();
    };

    ws.onerror = () => {
      // Let onclose drive reconnect.
    };
  }

  disconnect(): void {
    this.clearReconnect();
    if (this.ws) {
      try {
        this.ws.close();
      } catch {
        // ignore
      }
      this.ws = null;
    }
  }

  subscribe(symbol: string, timeframe: string): void {
    const sub = keyOf(symbol, timeframe);
    if (this.subscriptions.has(sub)) return;
    this.subscriptions.add(sub);
    this.connect();
    this.send({ type: 'subscribe', symbol, timeframe });
  }

  unsubscribe(symbol: string, timeframe: string): void {
    const sub = keyOf(symbol, timeframe);
    if (!this.subscriptions.has(sub)) return;
    this.subscriptions.delete(sub);
    this.send({ type: 'unsubscribe', symbol, timeframe } satisfies UnsubscribeMessage);
    // keep connection alive for other subs
  }

  private send(msg: LiveEngineClientMessage): void {
    if (!this.ws || this.ws.readyState !== WebSocket.OPEN) return;
    try {
      this.ws.send(JSON.stringify(msg));
    } catch {
      // ignore
    }
  }

  private enqueue(msg: LiveEngineMessage): void {
    this.pending.push(msg);
    if (this.flushTimer) return;
    this.flushTimer = window.setTimeout(() => this.flush(), this.uiThrottleMs);
  }

  private flush(): void {
    if (this.flushTimer) {
      window.clearTimeout(this.flushTimer);
      this.flushTimer = null;
    }
    const batch = this.pending;
    this.pending = [];
    for (const msg of batch) {
      for (const cb of this.listeners) cb(msg);
    }
  }

  private scheduleReconnect(): void {
    if (this.reconnectTimer) return;
    const base = 250 * Math.pow(2, this.reconnectAttempt++);
    const delay = Math.min(this.maxReconnectMs, base + Math.floor(Math.random() * 250));
    this.reconnectTimer = window.setTimeout(() => {
      this.reconnectTimer = null;
      this.connect();
    }, delay);
  }

  private clearReconnect(): void {
    if (this.reconnectTimer) {
      window.clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }
  }
}

