                            <div className="text-[9px] text-white/25 font-mono">
                              {t.closeTime ? t.closeTime.slice(0, 19).replace('T', ' ') : '—'} · #{t.externalTradeId}
                            </div>
                          </div>
                          {lbl ? (
                            <span className="text-[9px] px-2 py-0.5 rounded border border-white/10 bg-white/5 text-white/60">
